				sub, err := conn.SubscribeSync(subject)
				if err != nil {
					t.Fatal(err)
				}
				permissionDenied(conn, r.errors[clientIndex], subject)
				_ = sub.Unsubscribe()
			}
			flush(conn)
			select {
			case err := <-r.errors[clientIndex]:
				t.Fatalf("%s unexpected asynchronous error: %v", r.record.Cell, err)
			default:
			}
		}
	}
}

