		cfg.LinkSigner != "" && !nkeys.IsValidPublicAccountKey(cfg.LinkSigner) ||
		!entityid.Valid(cfg.DeploymentID) ||
		!entityid.Valid(cfg.ClusterID) ||
		cfg.ValidityHours < int(minValidity.Hours()) || cfg.ValidityHours > int(MaxValidity.Hours()) ||
		len(cfg.Slots) != 3 {
		return ErrMaterial
	}
	prefix, err := netip.ParsePrefix(cfg.SubnetCIDR)
	if err != nil || !prefix.Addr().Is4() || !prefix.Addr().IsPrivate() || prefix.Masked() != prefix {
		return ErrMaterial
	}
	for index, name := range []string{"controller-a", "controller-b", "controller-c"} {
		address, err := netip.ParseAddr(cfg.Slots[index].PrivateIP)
		if cfg.Slots[index].Name != name || err != nil || !address.Is4() || !prefix.Contains(address) ||
			address == prefix.Addr() || address == prefix.Addr().Next() {
			return ErrMaterial
		}
		for prior := range index {
			if cfg.Slots[prior].PrivateIP == cfg.Slots[index].PrivateIP {
				return ErrMaterial
			}
		}
	}
	return nil
}

func Generate(directory string, cfg Config, now time.Time) (Record, error) {
	if err := cfg.validate(); err != nil || !filepath.IsAbs(directory) || now.IsZero() || secureParents(directory) != nil {
		return Record{}, ErrMaterial
	}
	if _, err := os.Lstat(directory); err == nil {
		record, loadErr := Load(directory)
		if loadErr != nil || !sameConfig(record.Config, cfg) {
			return Record{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return Record{}, ErrMaterial
	}
	if err := os.Mkdir(directory, 0o700); err != nil {
		return Record{}, fmt.Errorf("create private material directory: %w", err)
	}
	files, public, err := build(cfg, now.UTC())
	if err != nil {
		return Record{}, err
	}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := Record{SchemaVersion: 1, Config: cfg, IssuedAt: now.UTC(),
		ExpiresAt: now.UTC().Add(time.Duration(cfg.ValidityHours) * time.Hour), Public: public}
	for name, body := range files {
		purpose, slot := classify(name)
		if purpose == "" || len(body) == 0 || len(body) > int(bootstrap.MaxSecretBytes) {
			return Record{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot,
			SHA256: digest(body), MaxBytes: int64(len(body))})
	}
	slices.SortFunc(record.Files, func(a, b File) int { return strings.Compare(a.Name, b.Name) })
	for _, file := range record.Files {
		if err := writeOnce(filepath.Join(directory, file.Name), files[file.Name]); err != nil {
			return Record{}, fmt.Errorf("write private material %s: %w", file.Name, err)
		}
	}
	metadata, err := json.Marshal(record)
	if err != nil {
		return Record{}, err
	}
	if err := writeOnce(filepath.Join(directory, metadataName), metadata); err != nil {
		return Record{}, err
	}
	if err := writeOnce(filepath.Join(directory, readyName), []byte(digest(metadata)+"\n")); err != nil {
		return Record{}, err
	}
	if err := syncDirectory(directory); err != nil {
		return Record{}, err
	}
	return record, nil
}

func Load(directory string) (Record, error) {
	if !filepath.IsAbs(directory) || secureParents(directory) != nil || secureDirectory(directory) != nil {
		return Record{}, ErrMaterial
	}
	metadata, err := readOwnedFile(filepath.Join(directory, metadataName), 1<<20)
	if err != nil {
		return Record{}, ErrMaterial
	}
	ready, err := readOwnedFile(filepath.Join(directory, readyName), 128)
	if err != nil || string(ready) != digest(metadata)+"\n" {
		return Record{}, ErrMaterial
	}
	var record Record
	if err := json.Unmarshal(metadata, &record, json.RejectUnknownMembers(true)); err != nil || record.SchemaVersion != 1 ||
		record.Config.validate() != nil ||
		len(record.Files) != len(expectedNames())+len(memberCANames)*boolInt(record.HasMemberCA()) ||
		record.ExpiresAt.Sub(record.IssuedAt) != time.Duration(record.Config.ValidityHours)*time.Hour {
		return Record{}, ErrMaterial
	}
	seen := make(map[string]bool, len(record.Files))
	for _, file := range record.Files {
		purpose, slot := classify(file.Name)
		if seen[file.Name] || file.Purpose != purpose || file.Slot != slot || purpose == "" ||
			file.MaxBytes <= 0 || file.MaxBytes > bootstrap.MaxSecretBytes {
			return Record{}, ErrMaterial
		}
		seen[file.Name] = true
		body, err := readOwnedFile(filepath.Join(directory, file.Name), file.MaxBytes)
		if err != nil || int64(len(body)) != file.MaxBytes || digest(body) != file.SHA256 {
			return Record{}, ErrMaterial
		}
		clear(body)
	}
	for _, name := range expectedNames() {
		if !seen[name] {
			return Record{}, ErrMaterial
		}
	}
	if seen[memberCANames[0]] != seen[memberCANames[1]] {
		return Record{}, ErrMaterial
	}
	entries, err := os.ReadDir(directory)
	if err != nil {
		return Record{}, ErrMaterial
	}
	allowed := map[string]bool{metadataName: true, readyName: true, journalName: true, journalTempName: true, journalLockName: true}
	for _, file := range record.Files {
		allowed[file.Name] = true
	}
	for _, entry := range entries {
		if !allowed[entry.Name()] {
			return Record{}, ErrMaterial
		}
		if entry.Name() == journalName {
			if _, err := readOwnedFile(filepath.Join(directory, entry.Name()), 1<<20); err != nil {
				return Record{}, ErrMaterial
			}
		} else if entry.Name() == journalTempName {
			if err := ownedRegular(filepath.Join(directory, entry.Name()), 0, 1<<20); err != nil {
				return Record{}, ErrMaterial
			}
		} else if entry.Name() == journalLockName {
			if err := ownedRegular(filepath.Join(directory, entry.Name()), 0, 0); err != nil {
				return Record{}, ErrMaterial
			}
		}
	}
	if len(entries) < len(record.Files)+2 {
		return Record{}, ErrMaterial
	}
	return record, nil
}

func expectedNames() []string {
	names := []string{"issuer-operator.seed", "issuer-system.seed", "issuer-cell.seed", "issuer-ca.key",
		"operator.jwt", "operator.creds", "operator-tls-cert.pem", "operator-tls-key.pem",
		"system.jwt", "cell.jwt", "system.creds", "ca.pem", "route-password",
		"ticket.pub", "ticket.key", "founder-peer.key", "founder-ledger.key",
		"controller-tls-issuer-cert.pem", "controller-tls-issuer-key.pem", "controller-account-signer.seed",
		"host-nats-issuer.seed", "host-tls-issuer-key.pem", "host-tls-issuer-cert.pem"}
	for _, slot := range []string{"controller-a", "controller-b", "controller-c"} {
		names = append(names, slot+".creds", slot+"-tls-cert.pem", slot+"-tls-key.pem", slot+"-response.key")
	}
	return names
}

func build(cfg Config, now time.Time) (map[string][]byte, Public, error) {
	files := make(map[string][]byte)
	expires := now.Add(time.Duration(cfg.ValidityHours) * time.Hour)
	op, err := nkeys.CreateOperator()
	if err != nil {
		return nil, Public{}, err
	}
	defer op.Wipe()
	sys, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer sys.Wipe()
	cell, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer cell.Wipe()
	opID, _ := op.PublicKey()
	sysID, _ := sys.PublicKey()
	cellID, _ := cell.PublicKey()
	hostIssuer, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer hostIssuer.Wipe()
	hostIssuerID, err := hostIssuer.PublicKey()
	if err != nil {
		return nil, Public{}, err
	}
	hostIssuerSeed, err := hostIssuer.Seed()
	if err != nil {
		return nil, Public{}, err
	}
	files["host-nats-issuer.seed"] = bytes.Clone(hostIssuerSeed)
	controllerSigner, err := nkeys.CreateAccount()
	if err != nil {
		return nil, Public{}, err
	}
	defer controllerSigner.Wipe()
	controllerSignerID, err := controllerSigner.PublicKey()
	if err != nil {
		return nil, Public{}, err
	}
	controllerSignerSeed, err := controllerSigner.Seed()
	if err != nil {
		return nil, Public{}, err
	}
	files["controller-account-signer.seed"] = bytes.Clone(controllerSignerSeed)
	for name, pair := range map[string]nkeys.KeyPair{"issuer-operator.seed": op, "issuer-system.seed": sys, "issuer-cell.seed": cell} {
		seed, err := pair.Seed()
		if err != nil {
			return nil, Public{}, err
		}
		files[name] = bytes.Clone(seed)
	}
	opClaim := jwt.NewOperatorClaims(opID)
	opClaim.SystemAccount = sysID
	opClaim.IssuedAt, opClaim.Expires = now.Unix(), expires.Unix()
	opJWT, err := opClaim.Encode(op)
	if err != nil {
		return nil, Public{}, err
	}
	sysClaim := jwt.NewAccountClaims(sysID)
	sysClaim.IssuedAt, sysClaim.Expires = now.Unix(), expires.Unix()
	sysJWT, err := sysClaim.Encode(op)
	if err != nil {
		return nil, Public{}, err
	}
	cellClaim := jwt.NewAccountClaims(cellID)
	cellClaim.IssuedAt, cellClaim.Expires = now.Unix(), expires.Unix()
	// Operator mode enables JetStream only for accounts whose JWT carries
	// JetStream limits. The server-wide store limit still bounds the cell.
	cellClaim.Limits.JetStreamLimits = jwt.JetStreamLimits{MemoryStorage: jwt.NoLimit, DiskStorage: jwt.NoLimit,
		Streams: jwt.NoLimit, Consumer: jwt.NoLimit}
	hostScope := expectedHostScope(cfg.Cell, hostIssuerID)
	cellClaim.SigningKeys.AddScopedSigner(hostScope)
	// The role signer (TS-651) from the start, so a new cell's roles get
	// NATS identities without a role-claim and broker-claim-apply.
	role, err := roleScope(hostIssuer)
	if err != nil {
		return nil, Public{}, err
	}
	cellClaim.SigningKeys.AddScopedSigner(role)
	cellClaim.SigningKeys.Add(controllerSignerID)
	if cfg.LinkSigner != "" {
		natscell.ApplyLink(cellClaim, cfg.LinkSigner)
	}
	cellJWT, err := cellClaim.Encode(op)
	if err != nil {
		return nil, Public{}, err
	}
	files["operator.jwt"], files["system.jwt"], files["cell.jwt"] = []byte(opJWT), []byte(sysJWT), []byte(cellJWT)
	systemUser, err := nkeys.CreateUser()
	if err != nil {
		return nil, Public{}, err
	}
	defer systemUser.Wipe()
	systemID, _ := systemUser.PublicKey()
	systemClaim := jwt.NewUserClaims(systemID)
	systemClaim.IssuerAccount = sysID
	systemClaim.IssuedAt, systemClaim.Expires = now.Unix(), expires.Unix()
	systemClaim.Pub.Allow = jwt.StringList{"$SYS.REQ.ACCOUNT." + cellID + ".CLAIMS.UPDATE"}
	systemClaim.Sub.Allow = jwt.StringList{inbox(cfg.Cell, systemID)}
	files["system.creds"], err = credentials(systemClaim, sys, systemUser)
	if err != nil {
		return nil, Public{}, err
	}
	operatorUser, err := nkeys.CreateUser()
	if err != nil {
		return nil, Public{}, err
	}
	defer operatorUser.Wipe()
	operatorID, err := operatorUser.PublicKey()
	if err != nil {
		return nil, Public{}, err
	}
	operatorClaim := jwt.NewUserClaims(operatorID)
	operatorClaim.IssuerAccount = cellID
	operatorClaim.IssuedAt, operatorClaim.Expires = now.Unix(), expires.Unix()
	operatorClaim.Pub.Allow = natscell.BrokerOperatorPublishPermissions(cfg.Cell)
	operatorClaim.Sub.Allow = jwt.StringList{inbox(cfg.Cell, operatorID)}
	files["operator.creds"], err = credentials(operatorClaim, cell, operatorUser)
	if err != nil {
		return nil, Public{}, err
	}
	caPEM, caKey, ca, err := makeCA(cfg, now, expires)
	if err != nil {
		return nil, Public{}, err
	}
	files["ca.pem"] = caPEM
	caDER, err := x509.MarshalECPrivateKey(caKey)
	if err != nil {
		return nil, Public{}, err
	}
	files["issuer-ca.key"] = pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: caDER})
	hostCAPEM, hostCAKeyPEM, err := makeHostIssuerCA(cfg, now, expires, ca, caKey)
	if err != nil {
		return nil, Public{}, err
	}
	files["host-tls-issuer-cert.pem"] = hostCAPEM
	files["host-tls-issuer-key.pem"] = hostCAKeyPEM
	files["controller-tls-issuer-cert.pem"], files["controller-tls-issuer-key.pem"], err = makeControllerIssuerCA(cfg, now, minTime(expires, now.Add(controllerIssuedLifetime)), ca, caKey)
	if err != nil {
		return nil, Public{}, err
	}
	// Every controller holds the cell's C# TerraBase member CA and signs
	// member certificates with it; database hosts never see the key.
	memberCell, err := naming.RegionCell(strings.ToUpper(cfg.Cell)).Name()
	if err != nil {
		return nil, Public{}, err
	}
	files["terrabase-member-ca.pem"], files["terrabase-member-ca.key"], err = terrabase.NewCA(memberCell, now)
	if err != nil {
		return nil, Public{}, err
	}
	operatorCert, operatorKey, err := makeOperatorLeaf(cfg, now, expires, ca, caKey)
	if err != nil {
		return nil, Public{}, err
	}
	files["operator-tls-cert.pem"], files["operator-tls-key.pem"] = operatorCert, operatorKey
	password := make([]byte, 32)
	if _, err := rand.Read(password); err != nil {
		return nil, Public{}, err
	}
	files["route-password"] = []byte(base64.RawURLEncoding.EncodeToString(password) + "\n")
	clear(password)
	ticketPub, ticketKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	ticketPub = bytes.Clone(ticketPub)
	files["ticket.pub"] = []byte(base64.StdEncoding.EncodeToString(ticketPub) + "\n")
	files["ticket.key"] = []byte(base64.StdEncoding.EncodeToString(ticketKey) + "\n")
	clear(ticketKey)
	peerPub, peerKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	ledgerPub, ledgerKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	peerPub, ledgerPub = bytes.Clone(peerPub), bytes.Clone(ledgerPub)
	files["founder-peer.key"], files["founder-ledger.key"] = bytes.Clone(peerKey), bytes.Clone(ledgerKey)
	clear(peerKey)
	clear(ledgerKey)
	responsePub, responseKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return nil, Public{}, err
	}
	responsePublic := base64.StdEncoding.EncodeToString(responsePub)
	responseWire := []byte(base64.StdEncoding.EncodeToString(responseKey) + "\n")
	clear(responseKey)
	defer clear(responseWire)
	for _, slot := range cfg.Slots {
		user, err := nkeys.CreateUser()
		if err != nil {
			return nil, Public{}, err
		}
		userID, _ := user.PublicKey()
		claim := jwt.NewUserClaims(userID)
		claim.IssuerAccount = cellID
		claim.IssuedAt, claim.Expires = now.Unix(), expires.Unix()
		claim.Pub.Allow = natscell.ControllerPublishes(cfg.Cell)
		// Fresh material has no link topology: the standalone cell is its own home.
		claim.Pub.Allow.Add(natscell.GlobalControllerPublishes()...)
		claim.Pub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow = jwt.StringList{inbox(cfg.Cell, userID), protocol.Broker(cfg.Cell, "ticket", ">"), protocol.Broker(cfg.Cell, "fence", slot.Name)}
		claim.Sub.Allow = append(claim.Sub.Allow, natscell.ControllerSubscriptions(cfg.Cell)...)
		claim.Sub.Allow.Add(natscell.GlobalControllerRequests()...)
		claim.Sub.Allow.Add(protocol.ObservabilityGrant(cfg.Cell))
		claim.Resp = &jwt.ResponsePermission{MaxMsgs: 1, Expires: 5 * time.Second}
		files[slot.Name+".creds"], err = credentials(claim, cell, user)
		user.Wipe()
		if err != nil {
			return nil, Public{}, err
		}
		cert, key, err := makeLeaf(cfg, slot, now, expires, ca, caKey)
		if err != nil {
			return nil, Public{}, err
		}
		files[slot.Name+"-tls-cert.pem"], files[slot.Name+"-tls-key.pem"] = cert, key
		files[slot.Name+"-response.key"] = bytes.Clone(responseWire)
	}
	public := Public{PeerSignerPublicKey: base64.StdEncoding.EncodeToString(peerPub), LedgerSignerPublicKey: base64.StdEncoding.EncodeToString(ledgerPub),
		TicketSignerPublicKey: base64.StdEncoding.EncodeToString(ticketPub), ControllerResponsePublicKey: responsePublic,
		HostNATSIssuerNKey: hostIssuerID, ControllerAccountSignerNKey: controllerSignerID, OperatorNKey: opID, SystemAccountNKey: sysID, CellAccountNKey: cellID}
	return files, public, nil
}

func classify(name string) (bootstrap.SecretPurpose, string) {
	switch name {
	case "issuer-operator.seed", "issuer-system.seed", "issuer-cell.seed", "issuer-ca.key",
		"operator.creds", "operator-tls-cert.pem", "operator-tls-key.pem":
		return "owner-only", ""
	case "founder-peer.key":
		return bootstrap.SecretSeedFounder, "controller-a"
	case "founder-ledger.key":
		return bootstrap.SecretSeedLedgerSigner, "controller-a"
	case "host-nats-issuer.seed", "host-tls-issuer-key.pem", "host-tls-issuer-cert.pem",
		"terrabase-member-ca.pem", "terrabase-member-ca.key":
		return bootstrap.SecretHostIssuer, ""
	case "controller-tls-issuer-cert.pem", "controller-tls-issuer-key.pem", "controller-account-signer.seed":
		return bootstrap.SecretControllerIssuer, ""
	case "operator.jwt", "system.jwt", "cell.jwt", "system.creds", "ca.pem", "route-password", "ticket.pub", "ticket.key":
		return bootstrap.SecretRegionalShared, ""
	}
	for _, slot := range []string{"controller-a", "controller-b", "controller-c"} {
		if slices.Contains([]string{slot + ".creds", slot + "-tls-cert.pem", slot + "-tls-key.pem", slot + "-response.key"}, name) {
			return bootstrap.SecretController, slot
		}
	}
	return "", ""
}

func writeOnce(path string, body []byte) error {
	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	defer file.Close()
	if _, err := file.Write(body); err != nil {
		return err
	}
	return file.Sync()
}

func syncDirectory(path string) error {
	dir, err := os.Open(path)
	if err != nil {
		return err
	}
	defer dir.Close()
	return dir.Sync()
}

func secureDirectory(path string) error {
	info, err := os.Lstat(path)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0o700 {
		return ErrMaterial
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); !ok || stat.Uid != uint32(os.Getuid()) {
		return ErrMaterial
	}
	return nil
}

func secureParents(path string) error {
	for parent := filepath.Dir(filepath.Clean(path)); ; parent = filepath.Dir(parent) {
		info, err := os.Lstat(parent)
		if err != nil || !info.IsDir() {
			return ErrMaterial
		}
		if filepath.Base(parent) == ".qualification" || filepath.Base(parent) == "evidence" {
			return ErrMaterial
		}
		if _, err := os.Lstat(filepath.Join(parent, ".git")); err == nil || !errors.Is(err, os.ErrNotExist) {
			return ErrMaterial
		}
		stat, ok := info.Sys().(*syscall.Stat_t)
		if !ok || stat.Uid != uint32(os.Getuid()) && stat.Uid != 0 ||
			info.Mode().Perm()&0o022 != 0 && !(stat.Uid == 0 && info.Mode()&os.ModeSticky != 0) {
			return ErrMaterial
		}
		if parent == string(filepath.Separator) {
			return nil
		}
	}
}

func readOwnedFile(path string, maximum int64) ([]byte, error) {
	if err := ownedRegular(path, 1, maximum); err != nil {
		return nil, err
	}
	before, err := os.Lstat(path)
	if err != nil {
		return nil, ErrMaterial
	}
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0)
	if err != nil {
		return nil, ErrMaterial
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	opened, err := file.Stat()
	if err != nil || !os.SameFile(before, opened) || opened.Size() != before.Size() ||
		!opened.Mode().IsRegular() || opened.Mode().Perm() != 0o600 || opened.Size() <= 0 || opened.Size() > maximum {
		return nil, ErrMaterial
	}
	stat, ok := opened.Sys().(*syscall.Stat_t)
	if !ok || stat.Uid != uint32(os.Getuid()) || stat.Nlink != 1 {
		return nil, ErrMaterial
	}
	body, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil || int64(len(body)) != opened.Size() {
		clear(body)
		return nil, ErrMaterial
	}
	return body, nil
}

func ownedRegular(path string, minimum, maximum int64) error {
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() || info.Mode().Perm() != 0o600 || info.Size() < minimum || info.Size() > maximum {
		return ErrMaterial
	}
	if stat, ok := info.Sys().(*syscall.Stat_t); !ok || stat.Uid != uint32(os.Getuid()) || stat.Nlink != 1 {
		return ErrMaterial
	}
	return nil
}

func ValidateLive(directory string, record Record) error {
	if _, err := Load(directory); err != nil {
		return err
	}
	if err := validateSignerFiles(directory, record); err != nil {
		return err
	}
	for _, slot := range record.Config.Slots {
		path := func(name string) string { return filepath.Join(directory, name) }
		tls := natscell.TLSFiles{CAFile: path("ca.pem"), CertFile: path(slot.Name + "-tls-cert.pem"), KeyFile: path(slot.Name + "-tls-key.pem")}
		routes := make([]string, 0, 2)
		for _, peer := range record.Config.Slots {
			if peer.Name != slot.Name {
				routes = append(routes, "nats-route://"+peer.PrivateIP+":6222")
			}
		}
		cfg := natscell.Config{Cell: record.Config.Cell, Instance: slot.Name, Replicas: 3, ClientRole: "controller",
			CredentialsFile: path(slot.Name + ".creds"), TLS: tls, Embedded: &natscell.Embedded{
				Host: slot.PrivateIP, Port: 4222, RouteHost: slot.PrivateIP, RoutePort: 6222, Routes: routes,
				StoreDir: path("unused-" + slot.Name), TLS: tls, RouteTLS: tls, RouteUser: "ts-route", RoutePasswordFile: path("route-password"),
				OperatorJWTFile: path("operator.jwt"), SystemJWTFile: path("system.jwt"), CellJWTFile: path("cell.jwt"),
				SystemCredentialsFile: path("system.creds"), TicketPublicKeyFile: path("ticket.pub"),
				BrokerIDs: []string{"controller-a", "controller-b", "controller-c"}}}
		if err := natscell.ValidateProductionCredentials(cfg); err != nil {
			return fmt.Errorf("controller %s credential validation: %w", slot.Name, err)
		}
		certPEM, err := readOwnedFile(path(slot.Name+"-tls-cert.pem"), 64<<10)
		if err != nil {
			return err
		}
		block, _ := pem.Decode(certPEM)
		if block == nil {
			return ErrMaterial
		}
		cert, err := x509.ParseCertificate(block.Bytes)
		if err != nil || !slices.ContainsFunc(cert.IPAddresses, func(ip net.IP) bool { return ip.Equal(net.ParseIP(slot.PrivateIP)) }) {
			return ErrMaterial
		}
	}
	return nil
}

func validateSignerFiles(directory string, record Record) error {
	read := func(name string) ([]byte, error) { return readOwnedFile(filepath.Join(directory, name), 64<<10) }
	issuerSeed, err := read("host-nats-issuer.seed")
	if err != nil {
		return ErrMaterial
	}
	issuer, err := nkeys.FromSeed(issuerSeed)
	clear(issuerSeed)
	if err != nil {
		return ErrMaterial
	}
	issuerID, err := issuer.PublicKey()
	if err != nil || issuerID != record.Public.HostNATSIssuerNKey {
		issuer.Wipe()
		return ErrMaterial
	}
	role, err := roleScope(issuer)
	issuer.Wipe()
	if err != nil {
		return ErrMaterial
	}
	cellWire, err := read("cell.jwt")
	if err != nil {
		return ErrMaterial
	}
	cellClaim, err := jwt.DecodeAccountClaims(string(cellWire))
	clear(cellWire)
	if err != nil {
		return ErrMaterial
	}
	scope, ok := cellClaim.SigningKeys.GetScope(issuerID)
	hostScope, ok := scope.(*jwt.UserScope)
	// Material generated before TS-663 has no role signer.
	bound, hasRole := cellClaim.SigningKeys.GetScope(role.Key)
	roleBound, _ := bound.(*jwt.UserScope)
	controllerScope, hasController := cellClaim.SigningKeys.GetScope(record.Public.ControllerAccountSignerNKey)
	// A link signer, when configured, is the only other scoped key.
	hasLink := record.Config.LinkSigner != ""
	if hasLink {
		if _, linked := cellClaim.SigningKeys.GetScope(record.Config.LinkSigner); !linked {
			return ErrMaterial
		}
	}
	if !ok || !reflect.DeepEqual(hostScope, expectedHostScope(record.Config.Cell, issuerID)) ||
		hasRole && !reflect.DeepEqual(roleBound, role) || !hasController || controllerScope != nil ||
		len(cellClaim.SigningKeys) != 2+boolInt(hasRole)+boolInt(hasLink) {
		return ErrMaterial
	}
	controller, err := loadRecordedControllerIssuer(record, read, time.Now())
	if err != nil {
		return err
	}
	controller.Wipe()
	operatorWire, err := read("operator.creds")
	if err != nil {
		return ErrMaterial
	}
	operatorJWT, err := nkeys.ParseDecoratedJWT(operatorWire)
	if err != nil {
		clear(operatorWire)
		return ErrMaterial
	}
	operatorClaim, err := jwt.DecodeUserClaims(operatorJWT)
	if err != nil {
		clear(operatorWire)
		return ErrMaterial
	}
	operatorPair, err := nkeys.ParseDecoratedUserNKey(operatorWire)
	clear(operatorWire)
	if err != nil {
		return ErrMaterial
	}
	operatorID, err := operatorPair.PublicKey()
	operatorPair.Wipe()
	if err != nil || operatorID != operatorClaim.Subject || operatorClaim.Issuer != cellClaim.Subject ||
		operatorClaim.IssuerAccount != cellClaim.Subject || !cellClaim.DidSign(operatorClaim) ||
		!slices.Equal(operatorClaim.Pub.Allow, natscell.BrokerOperatorPublishPermissions(record.Config.Cell)) ||
		!slices.Equal(operatorClaim.Sub.Allow, jwt.StringList{inbox(record.Config.Cell, operatorID)}) ||
		len(operatorClaim.Pub.Deny) != 0 || len(operatorClaim.Sub.Deny) != 0 || operatorClaim.Resp != nil {
		return ErrMaterial
	}
	for name, want := range map[string]string{"issuer-operator.seed": record.Public.OperatorNKey,
		"issuer-system.seed": record.Public.SystemAccountNKey, "issuer-cell.seed": record.Public.CellAccountNKey} {
		seed, err := read(name)
		if err != nil {
			return ErrMaterial
		}
		pair, err := nkeys.FromSeed(seed)
		clear(seed)
		if err != nil {
			return ErrMaterial
		}
		public, err := pair.PublicKey()
		pair.Wipe()
		if err != nil || public != want {
			return ErrMaterial
		}
	}
	for name, want := range map[string]string{"founder-peer.key": record.Public.PeerSignerPublicKey,
		"founder-ledger.key": record.Public.LedgerSignerPublicKey} {
		wire, err := read(name)
		if err != nil {
			return ErrMaterial
		}
		if !validEd25519Private(wire) || base64.StdEncoding.EncodeToString(ed25519.PrivateKey(wire).Public().(ed25519.PublicKey)) != want {
			clear(wire)
			return ErrMaterial
		}
		clear(wire)
	}
	ticket, err := read("ticket.key")
	if err != nil {
		return ErrMaterial
	}
	decoded, err := base64.StdEncoding.Strict().DecodeString(strings.TrimSuffix(string(ticket), "\n"))
	clear(ticket)
	if err != nil || !validEd25519Private(decoded) {
		clear(decoded)
		return ErrMaterial
	}
	public := base64.StdEncoding.EncodeToString(ed25519.PrivateKey(decoded).Public().(ed25519.PublicKey))
	clear(decoded)
	registered, err := read("ticket.pub")
	if err != nil || string(registered) != public+"\n" || public != record.Public.TicketSignerPublicKey {
		clear(registered)
		return ErrMaterial
	}
	clear(registered)
	for _, slot := range record.Config.Slots {
		wire, err := read(slot.Name + "-response.key")
		if err != nil {
			return ErrMaterial
		}
		decoded, err := base64.StdEncoding.Strict().DecodeString(strings.TrimSuffix(string(wire), "\n"))
		clear(wire)
		if err != nil || !validEd25519Private(decoded) {
			clear(decoded)
			return ErrMaterial
		}
		if base64.StdEncoding.EncodeToString(ed25519.PrivateKey(decoded).Public().(ed25519.PublicKey)) != record.Public.ControllerResponsePublicKey {
			clear(decoded)
			return ErrMaterial
		}
		clear(decoded)
	}
	caKeyWire, err := read("issuer-ca.key")
	if err != nil {
		return ErrMaterial
	}
	keyBlock, _ := pem.Decode(caKeyWire)
	clear(caKeyWire)
	if keyBlock == nil || keyBlock.Type != "EC PRIVATE KEY" {
		return ErrMaterial
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	if err != nil {
		return ErrMaterial
	}
	caWire, err := read("ca.pem")
	if err != nil {
		return ErrMaterial
	}
	certBlock, _ := pem.Decode(caWire)
	clear(caWire)
	if certBlock == nil || certBlock.Type != "CERTIFICATE" {
		return ErrMaterial
	}
	ca, err := x509.ParseCertificate(certBlock.Bytes)
	if err != nil || !key.PublicKey.Equal(ca.PublicKey) {
		return ErrMaterial
	}
	if ca.MaxPathLen != 1 || ca.MaxPathLenZero {
		return ErrMaterial
	}
	operatorCertWire, err := read("operator-tls-cert.pem")
	if err != nil {
		return ErrMaterial
	}
	operatorKeyWire, err := read("operator-tls-key.pem")
	if err != nil {
		clear(operatorCertWire)
		return ErrMaterial
	}
	operatorTLS, err := tls.X509KeyPair(operatorCertWire, operatorKeyWire)
	clear(operatorCertWire)
	clear(operatorKeyWire)
	if err != nil || len(operatorTLS.Certificate) != 1 {
		return ErrMaterial
	}
	operatorCert, err := x509.ParseCertificate(operatorTLS.Certificate[0])
	if err != nil || operatorCert.IsCA || operatorCert.KeyUsage != x509.KeyUsageDigitalSignature ||
		!slices.Equal(operatorCert.ExtKeyUsage, []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}) ||
		len(operatorCert.DNSNames) != 0 || len(operatorCert.URIs) != 0 || len(operatorCert.IPAddresses) != 0 ||
		operatorCert.NotAfter.After(ca.NotAfter) {
		return ErrMaterial
	}
	roots := x509.NewCertPool()
	roots.AddCert(ca)
	if _, err := operatorCert.Verify(x509.VerifyOptions{Roots: roots, CurrentTime: time.Now(),
		KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}}); err != nil {
		return ErrMaterial
	}
	hostKeyWire, err := read("host-tls-issuer-key.pem")
	if err != nil {
		return ErrMaterial
	}
	hostKeyBlock, rest := pem.Decode(hostKeyWire)
	clear(hostKeyWire)
	if hostKeyBlock == nil || hostKeyBlock.Type != "EC PRIVATE KEY" || len(bytes.TrimSpace(rest)) != 0 {
		return ErrMaterial
	}
	hostKey, err := x509.ParseECPrivateKey(hostKeyBlock.Bytes)
	if err != nil {
		return ErrMaterial
	}
	hostWire, err := read("host-tls-issuer-cert.pem")
	if err != nil {
		return ErrMaterial
	}
	hostBlock, rest := pem.Decode(hostWire)
	clear(hostWire)
	if hostBlock == nil || hostBlock.Type != "CERTIFICATE" || len(bytes.TrimSpace(rest)) != 0 {
		return ErrMaterial
	}
	hostCert, err := x509.ParseCertificate(hostBlock.Bytes)
	if err != nil || !hostKey.PublicKey.Equal(hostCert.PublicKey) || !hostCert.IsCA || !hostCert.MaxPathLenZero ||
		hostCert.KeyUsage != x509.KeyUsageCertSign || !slices.Equal(hostCert.ExtKeyUsage, []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}) ||
		!hostCert.PermittedDNSDomainsCritical ||
		!slices.Equal(hostCert.PermittedDNSDomains, []string{".hosts." + record.Config.Cell + ".terrascale.internal"}) ||
		!slices.Equal(hostCert.PermittedURIDomains, []string{"hosts." + record.Config.Cell + ".terrascale.internal"}) ||
		hostCert.CheckSignatureFrom(ca) != nil || hostCert.NotAfter.After(ca.NotAfter) {
		return ErrMaterial
	}
	// Controllers load the member CA exactly this way at start.
	if record.HasMemberCA() {
		if _, err := terrabase.LoadCA(filepath.Join(directory, memberCANames[0]),
			filepath.Join(directory, memberCANames[1])); err != nil {
			return ErrMaterial
		}
	}
	return nil
}

// memberCANames are the cell's C# TerraBase member CA. Generate always
// creates them; material generated before they existed lacks both and still
// loads, but cannot serve a TerraBase workload.
var memberCANames = [2]string{"terrabase-member-ca.pem", "terrabase-member-ca.key"}

// HasMemberCA reports whether the material carries the member CA pair.
func (record Record) HasMemberCA() bool {
	return slices.ContainsFunc(record.Files, func(file File) bool { return file.Name == memberCANames[0] })
}

func makeHostIssuerCA(cfg Config, now, expires time.Time, root *x509.Certificate, rootKey *ecdsa.PrivateKey) ([]byte, []byte, error) {
	domain := "hosts." + cfg.Cell + ".terrascale.internal"
	cert := &x509.Certificate{Subject: pkix.Name{CommonName: "TerraScale " + cfg.Cell + " host issuer"},
		NotBefore: now.Add(-time.Minute), NotAfter: expires, IsCA: true, BasicConstraintsValid: true, MaxPathLenZero: true,
		KeyUsage: x509.KeyUsageCertSign, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth},
		PermittedDNSDomainsCritical: true, PermittedDNSDomains: []string{"." + domain}, PermittedURIDomains: []string{domain}}
	return makeIssuerCA(cert, root, rootKey)
}

func ValidateProductionCredentials(cfg Config) error {
	if cfg.Embedded == nil || cfg.ClientRole != "" && cfg.ClientRole != "controller" {
		return errors.New("controller credential preflight requires a production embedded broker")
	}
	if err := cfg.validate(); err != nil {
		return err
	}
	e := cfg.Embedded
	operator, systemRaw, cellRaw, _, cellID, err := loadOperatorAccounts(e)
	if err != nil {
		return err
	}
	system, err := jwt.DecodeAccountClaims(systemRaw)
	if err != nil {
		return fmt.Errorf("decode system account JWT: %w", err)
	}
	cell, err := jwt.DecodeAccountClaims(cellRaw)
	if err != nil {
		return fmt.Errorf("decode cell account JWT: %w", err)
	}
	for label, claim := range map[string]jwt.Claims{"operator": operator, "system": system, "cell": cell} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s JWT is not currently valid", label)
		}
	}
	if err := validateSystemCredentials(e.SystemCredentialsFile, cfg.Cell, cellID, system.Subject); err != nil {
		return err
	}
	systemUser, _, err := credentialUser(e.SystemCredentialsFile)
	if err != nil {
		return fmt.Errorf("system account credentials: %w", err)
	}
	controller, _, err := credentialUser(cfg.CredentialsFile)
	if err != nil || credentialAccount(controller) != cellID {
		return errors.New("controller credentials do not belong to the regional cell account")
	}
	for label, claim := range map[string]*jwt.UserClaims{"system": systemUser, "controller": controller} {
		result := jwt.CreateValidationResults()
		claim.Validate(result)
		if result.IsBlocking(true) {
			return fmt.Errorf("%s user JWT is not currently valid", label)
		}
	}
	if err := ValidateBrokerControllerCredentials(cfg.CredentialsFile, cfg.Cell, cfg.Instance); err != nil {
		return err
	}
	// The optional membership user is checked at admission, not first at
	// shutdown when it is needed for the metadata step-down.
	if e.MembershipCredentialsFile != "" {
		if err := ValidateMembershipCredentials(e.MembershipCredentialsFile, cfg.Cell, system.Subject); err != nil {
			return err
		}
	}
	for label, files := range map[string]TLSFiles{"client": cfg.TLS, "listener": e.TLS, "route": e.RouteTLS} {
		if err := validateCurrentTLSFiles(files, label); err != nil {
			return fmt.Errorf("%s TLS material: %w", label, err)
		}
	}
	if cfg.Replicas > 1 {
		password, err := readPrivateFile(e.RoutePasswordFile, 4096)
		if err != nil {
			return fmt.Errorf("NATS route secret: %w", err)
		}
		defer clear(password)
		if len(strings.TrimSpace(string(password))) < 16 {
			return errors.New("NATS route secret is too short")
		}
	}
	return nil
}

func validateCurrentTLSFiles(files TLSFiles, role string) error {
	config, err := loadTLS(files, false)
	if err != nil {
		return err
	}
	if len(config.Certificates) != 1 || len(config.Certificates[0].Certificate) == 0 {
		return errors.New("TLS certificate chain is missing")
	}
	leaf, err := x509.ParseCertificate(config.Certificates[0].Certificate[0])
	if err != nil {
		return fmt.Errorf("parse TLS leaf certificate: %w", err)
	}
	return verifyTLSLeaf(leaf, config.Certificates[0].Certificate[1:], config.RootCAs, role)
}

func ValidateBrokerControllerCredentials(path, cell, broker string) error {
	data, err := readPrivateFile(path, 64<<10)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	defer clear(data)
	return ValidateBrokerControllerCredentialBytes(data, cell, broker)
}

// ValidateBrokerControllerCredentialBytes checks the same contract before a
// root-signed material generation installs controller credentials.
func ValidateBrokerControllerCredentialBytes(data []byte, cell, broker string) error {
	if !cellName.MatchString(cell) || !cellName.MatchString(broker) {
		return errors.New("broker controller credential cell or instance is invalid")
	}
	claim, public, err := credentialUserBytes(data)
	if err != nil {
		return fmt.Errorf("broker controller credentials: %w", err)
	}
	ticket := protocol.Broker(cell, "ticket", ">")
	fencePublish := protocol.Broker(cell, "fence", ">")
	fenceReceive := protocol.Broker(cell, "fence", broker)
	if !slices.Contains(claim.Pub.Allow, ticket) || !slices.Contains(claim.Pub.Allow, fencePublish) ||
		!slices.Contains(claim.Sub.Allow, ticket) || !slices.Contains(claim.Sub.Allow, fenceReceive) {
		return errors.New("broker controller credentials lack ticket or instance-bound fence grants")
	}
	allowedSubscriptions := map[string]bool{
		inboxPrefix(cell, public) + ".>": true,
		ticket:                           true, fenceReceive: true,
	}
	for _, subject := range ControllerSubscriptions(cell) {
		allowedSubscriptions[subject] = true
	}
	for _, subject := range GlobalControllerRequests() {
		allowedSubscriptions[subject] = true
	}
	// Optional read-only member telemetry (observability snapshots). The
	// issuer does not grant it today; it is accepted, not required.
	allowedSubscriptions[protocol.ObservabilityGrant(cell)] = true
	for _, grant := range claim.Sub.Allow {
		if !allowedSubscriptions[grant] {
			return fmt.Errorf("broker controller credentials have unscoped subscription %q", grant)
		}
	}
	if !slices.Contains(claim.Sub.Allow, inboxPrefix(cell, public)+".>") ||
		!slices.Contains(claim.Sub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.ManagedUpdatePrepareSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Sub.Allow, protocol.TerminalSubject(cell, ">")) ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 ||
		claim.Resp == nil || claim.Resp.MaxMsgs != 1 ||
		claim.Resp.Expires <= 0 || claim.Resp.Expires > 5*time.Second {
		return errors.New("broker controller credentials need a private inbox and one bounded response grant")
	}
	return nil
}

func ValidateBrokerOperatorCredentials(path, cell string) error {
	if !cellName.MatchString(cell) {
		return errors.New("broker operator credential cell is invalid")
	}
	claim, public, err := credentialUser(path)
	if err != nil {
		return fmt.Errorf("broker operator credentials: %w", err)
	}
	allowedPublishes := BrokerOperatorPublishPermissions(cell)
	for _, grant := range claim.Pub.Allow {
		if !slices.Contains(allowedPublishes, grant) {
			return fmt.Errorf("broker operator credentials have unscoped publish %q", grant)
		}
	}
	if !slices.Contains(claim.Pub.Allow, protocol.BrokerClaimApplySubject(cell)) ||
		!slices.Contains(claim.Pub.Allow, protocol.BackupOperationSubject(cell)) ||
		!slices.Contains(claim.Pub.Allow, protocol.TerminalSubject(cell, "plan")) ||
		!slices.Contains(claim.Pub.Allow, protocol.TerminalSubject(cell, "apply")) ||
		!slices.Contains(claim.Pub.Allow, protocol.TerminalSubject(cell, "status")) ||
		!slices.Contains(claim.Pub.Allow, "$JS.API.INFO") ||
		!slices.Contains(claim.Pub.Allow, "$JS.API.STREAM.INFO.TS_CONTROL_LOG") ||
		!slices.Contains(claim.Pub.Allow, "$JS.API.STREAM.MSG.GET.TS_CONTROL_LOG") ||
		len(claim.Sub.Allow) != 1 || claim.Sub.Allow[0] != inboxPrefix(cell, public)+".>" ||
		len(claim.Pub.Deny) != 0 || len(claim.Sub.Deny) != 0 {
		return errors.New("broker operator credentials need claim-apply publish and private reply grants")
	}
	return nil
}

func NewCA(cell string, now time.Time) (certificatePEM, keyPEM []byte, err error) {
	if !nameRE.MatchString(cell) {
		return nil, nil, errors.New("invalid cell name")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: "TerraBase member CA " + cell},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: now.Add(caValidity),
		KeyUsage:              x509.KeyUsageCertSign | x509.KeyUsageCRLSign,
		BasicConstraintsValid: true, IsCA: true, MaxPathLenZero: true,
	}
	der, err := x509.CreateCertificate(rand.Reader, template, template, &key.PublicKey, key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}),
		pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), nil
}

// LoadCA reads a member CA written by NewCA. The key must be a regular
// file that only this process user owns and can read.
func LoadCA(certificateFile, keyFile string) (*CA, error) {
	certificatePEM, err := os.ReadFile(certificateFile)
	if err != nil {
		return nil, err
	}
	keyPEM, err := readOwnerOnly(keyFile)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA key: %w", err)
	}
	pair, err := tls.X509KeyPair(certificatePEM, keyPEM)
	if err != nil {
		return nil, fmt.Errorf("terrabase member CA: %w", err)
	}
	certificate := pair.Leaf
	signer, ok := pair.PrivateKey.(crypto.Signer)
	if len(pair.Certificate) != 1 || !ok || !certificate.IsCA || certificate.KeyUsage&x509.KeyUsageCertSign == 0 {
		return nil, errors.New("terrabase member CA must be one CA certificate and its key")
	}
	return &CA{certificate: certificate, pem: certificatePEM, key: signer}, nil
}

// CertificatePEM is the CA certificate members trust.
func (ca *CA) CertificatePEM() []byte { return slices.Clone(ca.pem) }

// Issue signs a member's certificate request for its listed peer entry. The
// certificate names the member and its peer address, and serves both as the
// peer listener's server certificate and as the client certificate a member
// presents to other members.
func (ca *CA) Issue(csrDER []byte, peer Peer, now time.Time) ([]byte, error) {
	request, err := x509.ParseCertificateRequest(csrDER)
	if err != nil || request.CheckSignature() != nil {
		return nil, errors.New("invalid member certificate request")
	}
	if key, ok := request.PublicKey.(*ecdsa.PublicKey); !ok || key.Curve != elliptic.P256() {
		return nil, errors.New("member certificate request must use an ECDSA P-256 key")
	}
	notAfter := now.Add(memberValidity)
	if ca.certificate.NotAfter.Before(notAfter) {
		notAfter = ca.certificate.NotAfter
	}
	template := &x509.Certificate{
		SerialNumber: serial(), Subject: pkix.Name{CommonName: peer.Name},
		DNSNames: []string{peer.Name}, IPAddresses: []net.IP{peer.Address.Addr().AsSlice()},
		NotBefore: now.Add(-5 * time.Minute), NotAfter: notAfter,
		KeyUsage:    x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
	}
	der, err := x509.CreateCertificate(rand.Reader, template, ca.certificate, request.PublicKey, ca.key)
	if err != nil {
		return nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), nil
}

// NewMemberKey creates a member's private key and the certificate request
// the host sends to the controller. The key never leaves the host.
func NewMemberKey() (keyPEM, csrDER []byte, err error) {
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalPKCS8PrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	csrDER, err = x509.CreateCertificateRequest(rand.Reader, &x509.CertificateRequest{}, key)
	if err != nil {
		return nil, nil, err
	}
	return pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: keyDER}), csrDER, nil
}

func readOwnerOnly(path string) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	owner, ok := info.Sys().(*syscall.Stat_t)
	if !info.Mode().IsRegular() || info.Mode().Perm()&0o077 != 0 || !ok || owner.Uid != uint32(os.Getuid()) {
		return nil, errors.New("must be a regular file readable only by its owner, this process user")
	}
	return io.ReadAll(io.LimitReader(file, 64<<10))
}

func legacyMaterial(t *testing.T, directory string, record Record) Record {
	t.Helper()
	record.Files = slices.DeleteFunc(slices.Clone(record.Files), func(file File) bool {
		return slices.Contains(memberCANames[:], file.Name)
	})
	for _, name := range memberCANames {
		if err := os.Remove(filepath.Join(directory, name)); err != nil {
			t.Fatal(err)
		}
	}
	metadata, err := json.Marshal(record)
	if err != nil {
		t.Fatal(err)
	}
	for name, body := range map[string][]byte{metadataName: metadata, readyName: []byte(digest(metadata) + "\n")} {
		if err := os.WriteFile(filepath.Join(directory, name), body, 0o600); err != nil {
			t.Fatal(err)
		}
	}
	return record
}

func RoleClaim(materialDirectory, current string) (string, string, error) {
	material, err := Load(materialDirectory)
	if err != nil {
		return "", "", err
	}
	claim, err := jwt.DecodeAccountClaims(current)
	if err != nil || claim.Subject != material.Public.CellAccountNKey || claim.Issuer != material.Public.OperatorNKey {
		return "", "", errors.New("the current claim is not this material's cell account signed by its operator")
	}
	host, scoped := claim.SigningKeys.GetScope(material.Public.HostNATSIssuerNKey)
	if hostScope, ok := host.(*jwt.UserScope); !scoped || !ok ||
		!reflect.DeepEqual(hostScope, expectedHostScope(material.Config.Cell, material.Public.HostNATSIssuerNKey)) {
		return "", "", errors.New("the current claim lacks the material's host signer")
	}
	key := func(name, public string) (nkeys.KeyPair, error) {
		seed, err := readOwnedFile(filepath.Join(materialDirectory, name), 4096)
		if err != nil {
			return nil, ErrMaterial
		}
		pair, err := nkeys.FromSeed(bytes.TrimSpace(seed))
		clear(seed)
		if err != nil {
			return nil, ErrMaterial
		}
		if got, err := pair.PublicKey(); err != nil || got != public {
			pair.Wipe()
			return nil, ErrMaterial
		}
		return pair, nil
	}
	operator, err := key("issuer-operator.seed", material.Public.OperatorNKey)
	if err != nil {
		return "", "", err
	}
	defer operator.Wipe()
	hostIssuer, err := key("host-nats-issuer.seed", material.Public.HostNATSIssuerNKey)
	if err != nil {
		return "", "", err
	}
	scope, err := roleScope(hostIssuer)
	hostIssuer.Wipe()
	if err != nil {
		return "", "", err
	}
	issued := claim.IssuedAt
	claim.SigningKeys.AddScopedSigner(scope)
	raw, err := claim.Encode(operator)
	if err != nil {
		return "", "", fmt.Errorf("sign the cell account claim: %w", err)
	}
	// Encode stamps the time; brokers take only a strictly newer claim.
	if claim.IssuedAt <= issued {
		return "", "", errors.New("the current claim was issued this second; run again")
	}
	return raw, scope.Key, nil
}

// roleScope is the cell account's role signer scope for the key the
// controllers derive from the host NATS issuer.
func roleScope(hostIssuer nkeys.KeyPair) (*jwt.UserScope, error) {
	signer, err := roleidentity.Signer(hostIssuer)
	if err != nil {
		return nil, err
	}
	public, err := signer.PublicKey()
	signer.Wipe()
	if err != nil {
		return nil, err
	}
	return roleidentity.Scope(public), nil
}

func withoutIssue(claim *jwt.AccountClaims) *jwt.AccountClaims {
	claim.IssuedAt, claim.ID = 0, ""
	return claim
}

func mustDecode(t *testing.T, raw string) *jwt.AccountClaims {
	t.Helper()
	claim, err := jwt.DecodeAccountClaims(raw)
	if err != nil {
		t.Fatal(err)
	}
	return claim
}

func LoadIssuer(cell, cellAccount, natsSeedPath, keyPath, certPath string, rootPEM []byte) (*Issuer, error) {
	if !validCellRegion(cell, strings.ToUpper(cell)) || !nkeys.IsValidPublicAccountKey(cellAccount) {
		return nil, errors.New("host issuer cell account is invalid")
	}
	seed, err := os.ReadFile(natsSeedPath)
	if err != nil || len(seed) == 0 || len(seed) > 4096 {
		return nil, errors.New("host NATS issuer seed is unavailable")
	}
	defer clear(seed)
	pair, err := nkeys.FromSeed([]byte(strings.TrimSpace(string(seed))))
	if err != nil {
		return nil, fmt.Errorf("parse host NATS issuer seed: %w", err)
	}
	keyPEM, err := os.ReadFile(keyPath)
	if err != nil || len(keyPEM) == 0 || len(keyPEM) > 8192 {
		pair.Wipe()
		return nil, errors.New("host TLS issuer key is unavailable")
	}
	defer clear(keyPEM)
	certPEM, err := os.ReadFile(certPath)
	if err != nil || len(certPEM) == 0 || len(certPEM) > 8192 {
		pair.Wipe()
		return nil, errors.New("host TLS issuer certificate is unavailable")
	}
	var roots []*x509.Certificate
	for rest := rootPEM; ; {
		var block *pem.Block
		if block, rest = pem.Decode(rest); block == nil {
			if len(strings.TrimSpace(string(rest))) != 0 {
				pair.Wipe()
				return nil, errors.New("host TLS regional root has trailing data")
			}
			break
		}
		root, err := x509.ParseCertificate(block.Bytes)
		if block.Type != "CERTIFICATE" || err != nil {
			pair.Wipe()
			return nil, errors.New("host TLS regional root is invalid")
		}
		roots = append(roots, root)
	}
	key, cert, root, err := ParseTLSIssuer(keyPEM, certPEM, roots)
	if err != nil {
		pair.Wipe()
		return nil, err
	}
	return &Issuer{CellAccount: cellAccount, Cell: cell, NATSKey: pair, TLSKey: key, TLSCert: cert, TLSCertPEM: certPEM, Root: root}, nil
}

// ParseTLSIssuer checks the host TLS issuer: one EC key and one certificate,
// each a single PEM block, that match; the certificate is a client-only,
// path-length-zero intermediate signed by one of roots and is not itself a
// root. It returns the root that signed it.
func ParseTLSIssuer(keyPEM, certPEM []byte, roots []*x509.Certificate) (*ecdsa.PrivateKey, *x509.Certificate, *x509.Certificate, error) {
	keyBlock, rest := pem.Decode(keyPEM)
	if keyBlock == nil || keyBlock.Type != "EC PRIVATE KEY" || len(strings.TrimSpace(string(rest))) != 0 {
		return nil, nil, nil, errors.New("host TLS issuer key format is invalid")
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	if err != nil {
		return nil, nil, nil, err
	}
	certBlock, rest := pem.Decode(certPEM)
	if certBlock == nil || certBlock.Type != "CERTIFICATE" || len(strings.TrimSpace(string(rest))) != 0 {
		return nil, nil, nil, errors.New("host TLS issuer certificate format is invalid")
	}
	cert, err := x509.ParseCertificate(certBlock.Bytes)
	if err != nil {
		return nil, nil, nil, err
	}
	var signer *x509.Certificate
	for _, root := range roots {
		if root.Equal(cert) {
			return nil, nil, nil, errors.New("host TLS issuer is a regional root")
		}
		if signer == nil && cert.CheckSignatureFrom(root) == nil {
			signer = root
		}
	}
	public, keyIsECDSA := cert.PublicKey.(*ecdsa.PublicKey)
	if signer == nil || cert.CheckSignatureFrom(cert) == nil || !cert.IsCA || !cert.MaxPathLenZero ||
		cert.KeyUsage&x509.KeyUsageCertSign == 0 || len(cert.ExtKeyUsage) != 1 || cert.ExtKeyUsage[0] != x509.ExtKeyUsageClientAuth ||
		!keyIsECDSA || !public.Equal(&key.PublicKey) {
		return nil, nil, nil, errors.New("host TLS issuer is not a root-signed client-only intermediate")
	}
	return key, cert, signer, nil
}

func (issuer *Issuer) ValidateRoleScope(raw string) error {
	if issuer == nil || issuer.NATSKey == nil {
		return errors.New("host NATS issuer is unavailable")
	}
	account, err := jwt.DecodeAccountClaims(raw)
	if err != nil || account.Subject != issuer.CellAccount {
		return errors.New("cell account claim is invalid")
	}
	signer, err := roleidentity.Signer(issuer.NATSKey)
	if err != nil {
		return err
	}
	public, err := signer.PublicKey()
	signer.Wipe()
	if err != nil {
		return err
	}
	bound, ok := account.SigningKeys.GetScope(public)
	scope, scoped := bound.(*jwt.UserScope)
	if !ok || !scoped || !reflect.DeepEqual(scope, roleidentity.Scope(public)) {
		return errors.New("the cell account has no role signer; apply ts-orch bootstrap role-claim (docs/broker-claim-rotation.md)")
	}
	return nil
}

type fakeSecret struct {
	id, name, content string
}

type fakeVault struct {
	target          VaultTarget
	region          string
	byName          map[string]fakeSecret
	byID            map[string]fakeSecret
	create          int
	uncertain       bool
	failBeforeStore bool
	wrongBytes      bool
	wrongSecretKind bool
	duplicate       bool
	tokens          []string
}

func newFakeVault(target VaultTarget) *fakeVault {
	return &fakeVault{target: target, region: strings.Split(target.VaultOCID, ".")[3],
		byName: make(map[string]fakeSecret), byID: make(map[string]fakeSecret)}
}

func (fake *fakeVault) ListSecrets(_ context.Context, request ocivault.ListSecretsRequest) (ocivault.ListSecretsResponse, error) {
	if request.CompartmentId == nil || *request.CompartmentId != fake.target.CompartmentOCID || request.VaultId == nil ||
		*request.VaultId != fake.target.VaultOCID || request.Name == nil {
		return ocivault.ListSecretsResponse{}, errors.New("wrong target")
	}
	if item, ok := fake.byName[*request.Name]; ok {
		items := []ocivault.SecretSummary{{Id: new(item.id), SecretName: new(item.name),
			CompartmentId: new(fake.target.CompartmentOCID), VaultId: new(fake.target.VaultOCID),
			LifecycleState: ocivault.SecretSummaryLifecycleStateActive}}
		if fake.duplicate {
			items = append(items, items[0])
		}
		return ocivault.ListSecretsResponse{Items: items}, nil
	}
	return ocivault.ListSecretsResponse{}, nil
}

func (fake *fakeVault) CreateSecret(_ context.Context, request ocivault.CreateSecretRequest) (ocivault.CreateSecretResponse, error) {
	if request.SecretName == nil || request.OpcRetryToken == nil || request.CompartmentId == nil ||
		*request.CompartmentId != fake.target.CompartmentOCID || request.VaultId == nil ||
		*request.VaultId != fake.target.VaultOCID || request.KeyId == nil || *request.KeyId != fake.target.KMSKeyOCID {
		return ocivault.CreateSecretResponse{}, errors.New("wrong create target")
	}
	content, ok := request.SecretContent.(ocivault.Base64SecretContentDetails)
	if !ok || content.Content == nil {
		return ocivault.CreateSecretResponse{}, errors.New("wrong content type")
	}
	fake.create++
	fake.tokens = append(fake.tokens, *request.OpcRetryToken)
	if fake.failBeforeStore {
		fake.failBeforeStore = false
		return ocivault.CreateSecretResponse{}, errors.New("create outcome unknown")
	}
	kind := "vaultsecret"
	if fake.wrongSecretKind {
		kind = "secret"
	}
	item := fakeSecret{id: fmt.Sprintf("ocid1.%s.oc1.%s.ffvlrlvkaaaw6.a%d", kind, fake.region, fake.create), name: *request.SecretName, content: *content.Content}
	fake.byName[item.name], fake.byID[item.id] = item, item
	if fake.uncertain {
		fake.uncertain = false
		return ocivault.CreateSecretResponse{}, errors.New("uncertain transport")
	}
	return ocivault.CreateSecretResponse{Secret: ocivault.Secret{Id: new(item.id)}}, nil
}

func (fake *fakeVault) GetSecret(_ context.Context, request ocivault.GetSecretRequest) (ocivault.GetSecretResponse, error) {
	if request.SecretId == nil {
		return ocivault.GetSecretResponse{}, errors.New("missing id")
	}
	item, ok := fake.byID[*request.SecretId]
	if !ok {
		return ocivault.GetSecretResponse{}, errors.New("missing secret")
	}
	return ocivault.GetSecretResponse{Secret: ocivault.Secret{Id: new(item.id), SecretName: new(item.name),
		CompartmentId: new(fake.target.CompartmentOCID), VaultId: new(fake.target.VaultOCID),
		KeyId: new(fake.target.KMSKeyOCID), LifecycleState: ocivault.SecretLifecycleStateActive,
		CurrentVersionNumber: new(int64(1))}}, nil
}

func (fake *fakeVault) GetSecretBundle(_ context.Context, request ocisecrets.GetSecretBundleRequest) (ocisecrets.GetSecretBundleResponse, error) {
	if request.SecretId == nil || request.VersionNumber == nil || *request.VersionNumber != 1 {
		return ocisecrets.GetSecretBundleResponse{}, errors.New("not exact version one")
	}
	item, ok := fake.byID[*request.SecretId]
	if !ok {
		return ocisecrets.GetSecretBundleResponse{}, errors.New("missing bundle")
	}
	if fake.wrongBytes {
		item.content = base64.StdEncoding.EncodeToString([]byte("wrong"))
	}
	return ocisecrets.GetSecretBundleResponse{SecretBundle: ocisecrets.SecretBundle{SecretId: new(item.id),
		VersionNumber: new(int64(1)), SecretBundleContent: ocisecrets.Base64SecretBundleContentDetails{Content: new(item.content)}}}, nil
}

