func supportedMaterialRegion(region string) bool { return catalog.IsOCIRegion(region) }

func regionalResourceOCID(id, kind, region string) bool {
	prefix := "ocid1." + kind + ".oc1." + region + "."
	return strings.HasPrefix(id, prefix) && resourcePartRE.MatchString(strings.TrimPrefix(id, prefix))
}

func (target VaultTarget) validate(region string) error {
	if !supportedMaterialRegion(region) || !compartmentRE.MatchString(target.CompartmentOCID) ||
		!regionalResourceOCID(target.VaultOCID, "vault", region) ||
		!regionalResourceOCID(target.KMSKeyOCID, "key", region) {
		return ErrProvision
	}
	return nil
}

// Validate binds the control-compartment Vault target to a mapped OCI region.
func (target VaultTarget) Validate(region string) error { return target.validate(region) }

func Provision(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time) (Publication, error) {
	return provision(ctx, directory, target, management, bundles, now, nil)
}

// ProvisionDurable checkpoints the exact publication journal to the source
// authority before any secret create, preserving recovery across host loss.
func ProvisionDurable(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time, checkpoint func([]byte) error) (Publication, error) {
	if checkpoint == nil {
		return Publication{}, ErrProvision
	}
	return provision(ctx, directory, target, management, bundles, now, checkpoint)
}

func provision(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time, checkpoint func([]byte) error) (Publication, error) {
	if management == nil || bundles == nil || ctx.Err() != nil {
		return Publication{}, ErrProvision
	}
	record, err := Load(directory)
	if err != nil || target.validate(record.Config.Region) != nil || !now.Before(record.ExpiresAt) {
		return Publication{}, ErrProvision
	}
	if err := ValidateLive(directory, record); err != nil {
		return Publication{}, ErrProvision
	}
	ctx, cancel := context.WithDeadline(ctx, record.ExpiresAt)
	defer cancel()
	lockFD, err := syscall.Open(filepath.Join(directory, journalLockName), syscall.O_RDWR|syscall.O_CREAT|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0o600)
	if err != nil {
		return Publication{}, ErrProvision
	}
	lock := os.NewFile(uintptr(lockFD), journalLockName)
	defer lock.Close()
	if err := ownedRegular(filepath.Join(directory, journalLockName), 0, 0); err != nil {
		return Publication{}, ErrProvision
	}
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
		return Publication{}, ErrProvision
	}
	defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
	metadata, err := readOwnedFile(filepath.Join(directory, metadataName), 1<<20)
	if err != nil {
		return Publication{}, ErrProvision
	}
	materialDigest := digest(metadata)
	state, err := loadJournal(ctx, directory, record, target, materialDigest, checkpoint)
	if err != nil {
		return Publication{}, err
	}
	for index := range state.Entries {
		if ctx.Err() != nil {
			return Publication{}, ErrProvision
		}
		entry := &state.Entries[index]
		file, ok := findFile(record, entry.FileName)
		if !ok {
			return Publication{}, ErrProvision
		}
		if err := publishOne(ctx, directory, target, record.Config.Region, management, bundles, file, entry, &state, now, checkpoint); err != nil {
			return Publication{}, err
		}
	}
	result := Publication{SchemaVersion: 1, Target: target, MaterialSHA256: materialDigest}
	for _, entry := range state.Entries {
		file, _ := findFile(record, entry.FileName)
		if !entry.Verified || entry.SecretOCID == "" {
			return Publication{}, ErrProvision
		}
		result.References = append(result.References, PublicReference{SecretName: entry.Name, Reference: bootstrap.SecretReference{
			Purpose: file.Purpose, Slot: file.Slot, SecretOCID: entry.SecretOCID, VersionNumber: 1,
			SHA256: file.SHA256, MaxBytes: file.MaxBytes, TargetFile: file.Name}})
	}
	return result, nil
}

func loadJournal(ctx context.Context, directory string, record Record, target VaultTarget, materialDigest string, checkpoint func([]byte) error) (journal, error) {
	path := filepath.Join(directory, journalName)
	wire, err := readOwnedFile(path, 1<<20)
	if err != nil {
		if _, statErr := os.Lstat(path); !errors.Is(statErr, os.ErrNotExist) {
			return journal{}, ErrProvision
		}
		state := journal{SchemaVersion: 1, Target: target, MaterialSHA256: materialDigest}
		for _, file := range record.Files {
			if file.Purpose == "owner-only" {
				continue
			}
			state.Entries = append(state.Entries, journalEntry{Name: secretName(record.Config, file), FileName: file.Name, RetryToken: uuid.New().String()})
		}
		if len(state.Entries) == 0 || len(state.Entries) > 64 {
			return journal{}, ErrProvision
		}
		if err := checkpointJournal(ctx, directory, state, checkpoint); err != nil {
			return journal{}, err
		}
		return state, nil
	}
	var state journal
	if err := json.Unmarshal(wire, &state); err != nil || state.SchemaVersion != 1 || state.Target != target ||
		state.MaterialSHA256 != materialDigest || len(state.Entries) == 0 || len(state.Entries) > 64 {
		return journal{}, ErrProvision
	}
	expected := 0
	for _, file := range record.Files {
		if file.Purpose != "owner-only" {
			expected++
		}
	}
	if len(state.Entries) != expected {
		return journal{}, ErrProvision
	}
	for index, entry := range state.Entries {
		file, ok := findFile(record, entry.FileName)
		if !ok || file.Purpose == "owner-only" || entry.Name != secretName(record.Config, file) ||
			entry.Verified && !regionalResourceOCID(entry.SecretOCID, "vaultsecret", record.Config.Region) ||
			entry.SecretOCID != "" && !regionalResourceOCID(entry.SecretOCID, "vaultsecret", record.Config.Region) ||
			entry.Verified && entry.SentAt.IsZero() || entry.SecretOCID != "" && !entry.Verified ||
			!entry.SentAt.IsZero() && entry.SentAt.Before(record.IssuedAt) {
			return journal{}, ErrProvision
		}
		if _, err := uuid.Parse(entry.RetryToken); err != nil {
			return journal{}, ErrProvision
		}
		if index > 0 && state.Entries[index-1].FileName >= entry.FileName {
			return journal{}, ErrProvision
		}
	}
	if err := checkpointJournal(ctx, directory, state, checkpoint); err != nil {
		return journal{}, err
	}
	return state, nil
}

func checkpointJournal(ctx context.Context, directory string, state journal, checkpoint func([]byte) error) error {
	if err := saveJournal(ctx, directory, state); err != nil {
		return err
	}
	if checkpoint == nil {
		return nil
	}
	wire, err := readOwnedFile(filepath.Join(directory, journalName), 1<<20)
	if err != nil {
		return err
	}
	defer clear(wire)
	if err := GuardPublication(ctx); err != nil {
		return err
	}
	return checkpoint(wire)
}

func publishOne(ctx context.Context, directory string, target VaultTarget, region string, management VaultClient, bundles BundleClient,
	file File, entry *journalEntry, state *journal, now time.Time, checkpoint func([]byte) error) error {
	id, found, err := lookup(ctx, target, region, entry.Name, management)
	if err != nil {
		return ErrProvision
	}
	if found {
		if entry.SentAt.IsZero() {
			return ErrProvision
		}
		if entry.SecretOCID != "" && entry.SecretOCID != id {
			return ErrProvision
		}
		if err := verifyBundle(ctx, target, id, entry.Name, file, management, bundles); err != nil {
			return ErrProvision
		}
		entry.SecretOCID, entry.Verified = id, true
		return checkpointJournal(ctx, directory, *state, checkpoint)
	}
	if entry.Verified || entry.SecretOCID != "" || !entry.SentAt.IsZero() && (now.Before(entry.SentAt) || now.Sub(entry.SentAt) >= retryWindow) {
		return ErrProvision
	}
	if entry.SentAt.IsZero() {
		entry.SentAt = now.UTC()
		if err := checkpointJournal(ctx, directory, *state, checkpoint); err != nil {
			return err
		}
	}
	if ctx.Err() != nil {
		return ErrProvision
	}
	body, err := readOwnedFile(filepath.Join(directory, file.Name), file.MaxBytes)
	if err != nil || digest(body) != file.SHA256 {
		clear(body)
		return ErrProvision
	}
	encoded := base64.StdEncoding.EncodeToString(body)
	clear(body)
	if ctx.Err() != nil {
		return ErrProvision
	}
	if checkpoint != nil {
		if err := checkpointJournal(ctx, directory, *state, checkpoint); err != nil {
			encoded = ""
			return err
		}
	}
	response, err := management.CreateSecret(ociclient.RequestContext(ctx), ocivault.CreateSecretRequest{
		CreateSecretDetails: ocivault.CreateSecretDetails{
			CompartmentId: new(target.CompartmentOCID), VaultId: new(target.VaultOCID), KeyId: new(target.KMSKeyOCID),
			SecretName: new(entry.Name), Description: new("Initial TerraScale regional controller credential material."),
			SecretContent: ocivault.Base64SecretContentDetails{Content: new(encoded), Stage: ocivault.SecretContentDetailsStageCurrent}},
		OpcRetryToken: new(entry.RetryToken),
	})
	encoded = ""
	if err != nil || response.Id == nil || !regionalResourceOCID(*response.Id, "vaultsecret", region) {
		return ErrProvision
	}
	if err := verifyBundle(ctx, target, *response.Id, entry.Name, file, management, bundles); err != nil {
		return ErrProvision
	}
	entry.SecretOCID, entry.Verified = *response.Id, true
	return checkpointJournal(ctx, directory, *state, checkpoint)
}

func lookup(ctx context.Context, target VaultTarget, region, name string, client VaultClient) (string, bool, error) {
	var page *string
	var found string
	for range 32 {
		response, err := client.ListSecrets(ociclient.RequestContext(ctx), ocivault.ListSecretsRequest{CompartmentId: new(target.CompartmentOCID), VaultId: new(target.VaultOCID), Name: new(name), Page: page})
		if err != nil {
			return "", false, err
		}
		for _, item := range response.Items {
			if item.SecretName == nil || *item.SecretName != name || item.CompartmentId == nil || *item.CompartmentId != target.CompartmentOCID ||
				item.VaultId == nil || *item.VaultId != target.VaultOCID || item.Id == nil || item.LifecycleState != ocivault.SecretSummaryLifecycleStateActive &&
				item.LifecycleState != ocivault.SecretSummaryLifecycleStateCreating {
				return "", false, ErrProvision
			}
			if !regionalResourceOCID(*item.Id, "vaultsecret", region) || found != "" {
				return "", false, ErrProvision
			}
			found = *item.Id
		}
		if response.OpcNextPage == nil {
			return found, found != "", nil
		}
		page = response.OpcNextPage
	}
	return "", false, ErrProvision
}

func verifyBundle(ctx context.Context, target VaultTarget, id, name string, file File, management VaultClient, bundles BundleClient) error {
	deadline := time.Now().Add(time.Minute)
	for {
		response, err := management.GetSecret(ociclient.RequestContext(ctx), ocivault.GetSecretRequest{SecretId: new(id)})
		if err == nil && response.Id != nil && *response.Id == id && response.CompartmentId != nil &&
			*response.CompartmentId == target.CompartmentOCID && response.VaultId != nil && *response.VaultId == target.VaultOCID &&
			response.KeyId != nil && *response.KeyId == target.KMSKeyOCID &&
			response.SecretName != nil && *response.SecretName == name && response.LifecycleState == ocivault.SecretLifecycleStateActive &&
			response.CurrentVersionNumber != nil {
			if *response.CurrentVersionNumber != 1 {
				return ErrProvision
			}
			break
		}
		if time.Now().After(deadline) || ctx.Err() != nil {
			return ErrProvision
		}
		select {
		case <-ctx.Done():
			return ErrProvision
		case <-time.After(time.Second):
		}
	}
	version := int64(1)
	response, err := bundles.GetSecretBundle(ociclient.RequestContext(ctx), ocisecrets.GetSecretBundleRequest{SecretId: new(id), VersionNumber: &version})
	if err != nil || response.SecretId == nil || *response.SecretId != id || response.VersionNumber == nil || *response.VersionNumber != 1 {
		return ErrProvision
	}
	content, ok := response.SecretBundleContent.(ocisecrets.Base64SecretBundleContentDetails)
	if !ok {
		pointer, pointerOK := response.SecretBundleContent.(*ocisecrets.Base64SecretBundleContentDetails)
		if !pointerOK || pointer == nil {
			return ErrProvision
		}
		content = *pointer
	}
	if content.Content == nil {
		return ErrProvision
	}
	body, err := base64.StdEncoding.Strict().DecodeString(*content.Content)
	if err != nil || int64(len(body)) != file.MaxBytes {
		clear(body)
		return ErrProvision
	}
	defer clear(body)
	want, err := hex.DecodeString(file.SHA256)
	if err != nil {
		return ErrProvision
	}
	sum := sha256.Sum256(body)
	if subtle.ConstantTimeCompare(sum[:], want) != 1 {
		return ErrProvision
	}
	return nil
}

func saveJournal(ctx context.Context, directory string, state journal) error {
	wire, err := json.Marshal(state)
	if err != nil {
		return ErrProvision
	}
	temporary := filepath.Join(directory, journalTempName)
	if _, err := os.Lstat(temporary); err == nil {
		if err := ownedRegular(temporary, 0, 1<<20); err != nil {
			return ErrProvision
		}
		if err := os.Remove(temporary); err != nil {
			return ErrProvision
		}
	} else if !errors.Is(err, os.ErrNotExist) {
		return ErrProvision
	}
	if err := writeOnce(temporary, wire); err != nil {
		return ErrProvision
	}
	defer os.Remove(temporary)
	if err := GuardPublication(ctx); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(directory, journalName)); err != nil {
		return ErrProvision
	}
	if err := syncDirectory(directory); err != nil {
		return ErrProvision
	}
	return GuardPublication(ctx)
}

func Lookup(cell string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Cell == cell {
			return entry, true
		}
	}
	return Entry{}, false
}

// IsCell reports whether cell is an exact upper-case supported cell code.
func IsCell(cell string) bool {
	_, ok := Lookup(cell)
	return ok
}

// OCIRegion returns the OCI region for an exact cell code, or "" when the cell
// is not supported.
func OCIRegion(cell string) string {
	entry, _ := Lookup(cell)
	return entry.OCIRegion
}

// IsOCIRegion reports whether region is the OCI identifier of a supported cell.
func IsOCIRegion(region string) bool {
	_, ok := CellForOCIRegion(region)
	return ok
}

// CellForOCIRegion maps an exact OCI region identifier back to its cell.
func CellForOCIRegion(region string) (Entry, bool) {
	for _, entry := range entries {
		if entry.OCIRegion == region {
			return entry, true
		}
	}
	return Entry{}, false
}

func Start(ctx context.Context, cfg Config) (_ *Runtime, err error) {
	return start(ctx, cfg, false)
}

// StartIdentityRekey joins only the existing regional quorum. The caller must
// verify its root checkpoint before opening it and close it after shared reset
// completion before starting normal external transports on the same store.
func StartIdentityRekey(ctx context.Context, cfg Config) (*Runtime, error) {
	if cfg.Embedded == nil {
		return nil, errors.New("identity rekey requires an installed production broker")
	}
	return start(ctx, cfg, true)
}

func start(ctx context.Context, cfg Config, identityRekey bool) (_ *Runtime, err error) {
	if err := cfg.validate(); err != nil {
		return nil, err
	}
	r := &Runtime{cell: cfg.Cell}
	defer func() {
		if err != nil {
			_ = r.Close()
		}
	}()
	if cfg.Embedded != nil {
		options, optionsErr := serverOptionsForStart(cfg, identityRekey)
		if optionsErr != nil {
			return nil, optionsErr
		}
		r.server, err = server.NewServer(options)
		if err != nil {
			return nil, fmt.Errorf("create embedded NATS: %w", err)
		}
		if err := pinNodeIdentity(cfg.Embedded.StoreDir, cfg.Cell, cfg.Instance, r.server.NodeName()); err != nil {
			return nil, fmt.Errorf("pin embedded NATS Raft identity: %w", err)
		}
		r.server.SetLoggerV2(natsLogger{}, false, false, false)
		r.serverName = options.ServerName
		for _, id := range cfg.Embedded.BrokerIDs {
			r.brokerNames = append(r.brokerNames, ServerName(cfg.Cell, id))
		}
		go r.server.Start()
		if !serverReady(ctx, r.server) {
			return nil, errors.New("embedded NATS did not become ready")
		}
		cfg.URL = r.server.ClientURL()
		r.resolver = options.AccountResolver.(*accountResolver)
		r.operator = options.TrustedOperators[0]
		if _, err := r.server.LookupAccount(r.resolver.cell); err != nil {
			return nil, fmt.Errorf("load regional cell account: %w", err)
		}
	}
	options, err := clientOptions(cfg)
	if err != nil {
		return nil, err
	}
	if cfg.Embedded != nil {
		options = append(options, nats.InProcessServer(r.server))
	}
	if cfg.ClientRole == "host" {
		// A blackholed peer must be detected well inside the host's 25-second
		// execution window. nats.go otherwise waits two minutes between PINGs.
		options = append(options,
			nats.PingInterval(2*time.Second), nats.MaxPingsOutstanding(2),
			nats.ReconnectWait(500*time.Millisecond),
			nats.DisconnectErrHandler(func(conn *nats.Conn, cause error) {
				r.logHostConnection("disconnected", conn, cause)
			}),
			nats.ReconnectHandler(func(conn *nats.Conn) {
				r.logHostConnection("reconnected", conn, nil)
			}),
		)
	}
	connectCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	connected := make(chan struct{})
	var connectErr, forwardErr error
	go func() {
		connectURL := cfg.URL
		if cfg.Embedded == nil {
			if len(cfg.OperatorForward) != 0 {
				var selected string
				selected, _, forwardErr = operatorForwarding(cfg)
				if forwardErr != nil {
					close(connected)
					return
				}
				connectURL = selected
			}
			connectURL = bridgeClientURLs(connectURL)
		}
		r.conn, connectErr = nats.Connect(connectURL, options...)
		close(connected)
	}()
	select {
	case <-connectCtx.Done():
		// nats.Connect has a bounded timeout of its own; wait for the goroutine
		// before cleaning up to avoid a late client after server shutdown.
		<-connected
		if forwardErr != nil {
			return nil, forwardErr
		}
		return nil, unavailable{connectCtx.Err()}
	case <-connected:
	}
	if forwardErr != nil {
		return nil, forwardErr
	}
	if connectErr != nil {
		err := fmt.Errorf("connect regional NATS: %w", connectErr)
		if errors.Is(connectErr, nats.ErrAuthorization) {
			// The brokers answered and refused these credentials.
			return nil, err
		}
		return nil, unavailable{err}
	}
	if cfg.Embedded != nil {
		systemCfg := cfg
		systemCfg.NKeySeedFile = ""
		systemCfg.CredentialsFile = cfg.Embedded.SystemCredentialsFile
		systemOptions, optionErr := clientOptions(systemCfg)
		if optionErr != nil {
			return nil, fmt.Errorf("system account client: %w", optionErr)
		}
		systemOptions = append(systemOptions, nats.InProcessServer(r.server))
		r.systemConn, err = nats.Connect(cfg.URL, systemOptions...)
		if err != nil {
			return nil, fmt.Errorf("connect internal system account: %w", err)
		}
		r.brokerTLS, err = NewReloadingTLS(cfg.Embedded.TLS, "listener")
		if err != nil {
			return nil, err
		}
		if !identityRekey {
			r.bridge, err = startBridge(r.server, net.JoinHostPort(cfg.Embedded.Host, fmt.Sprint(cfg.Embedded.Port)),
				r.brokerTLS.ServerConfig(), r.resolver.cell)
			if err != nil {
				return nil, err
			}
		}
	}
	if cfg.ClientRole == "host" {
		r.logHostConnection("connected", r.conn, nil)
	}
	r.js, err = jetstream.New(r.conn)
	if err != nil {
		return nil, fmt.Errorf("open regional JetStream: %w", err)
	}
	// A new R3 cell cannot elect a JetStream metadata leader until its peers
	// have also started. The app calls WaitForCluster before any mutations.
	if cfg.Replicas == 1 && cfg.ClientRole != "host" {
		infoCtx, infoCancel := context.WithTimeout(ctx, 10*time.Second)
		defer infoCancel()
		if _, err := r.js.AccountInfo(infoCtx); err != nil {
			return nil, unavailable{fmt.Errorf("regional JetStream unavailable: %w", err)}
		}
	}
	return r, nil
}

func startBridge(s *server.Server, address string, tlsConfig *tls.Config, account string) (*Bridge, error) {
	if s == nil || tlsConfig == nil || account == "" {
		return nil, errors.New("production broker bridge is incomplete")
	}
	listener, err := tls.Listen("tcp", address, tlsConfig)
	if err != nil {
		return nil, fmt.Errorf("listen for regional broker clients: %w", err)
	}
	b := &Bridge{server: s, listener: listener, account: account, pairs: make(map[*bridgePair]struct{}), listeners: make(map[net.Listener]struct{})}
	go b.accept(listener)
	return b, nil
}

func (b *Bridge) OpenUntil(sequence uint64, rawJWT string, deadline time.Time) error {
	if b == nil || sequence == 0 || rawJWT == "" || !time.Now().Before(deadline) {
		return errors.New("broker bridge ticket is invalid or expired")
	}
	if _, err := b.server.LookupAccount(b.account); err != nil {
		return fmt.Errorf("load broker account: %w", err)
	}
	accountz, err := b.server.Accountz(&server.AccountzOptions{Account: b.account})
	if err != nil || accountz.Account == nil || accountz.Account.Jwt != rawJWT {
		return errors.New("broker account JWT was not applied locally")
	}
	b.mu.Lock()
	if b.closed || sequence < b.floor {
		b.mu.Unlock()
		return errors.New("broker bridge is closed or claim sequence is stale")
	}
	var pairs map[*bridgePair]struct{}
	if b.open && (b.sequence != sequence || b.jwt != rawJWT) {
		pairs = b.fenceLocked()
	}
	b.sequence, b.jwt, b.deadline, b.open = sequence, rawJWT, deadline, true
	if b.timer != nil {
		b.timer.Stop()
	}
	b.timer = time.AfterFunc(time.Until(deadline), func() {
		b.mu.Lock()
		var expired map[*bridgePair]struct{}
		if b.open && b.sequence == sequence && b.deadline.Equal(deadline) {
			expired = b.fenceLocked()
		}
		b.mu.Unlock()
		closeBridgeExternal(expired)
	})
	b.mu.Unlock()
	closeBridgeExternal(pairs)
	return nil
}

func linkedRegions(t *testing.T) (linkedRegion, linkedRegion, time.Time) {
	t.Helper()
	root := t.TempDir()
	now := time.Now().UTC().Truncate(time.Second)
	sfoConfig := testConfig()
	sfoConfig.Region, sfoConfig.Cell, sfoConfig.ClusterID, sfoConfig.SubnetCIDR = "us-sanjose-1", "sfo", "00000000000000000000000002", "10.252.0.0/24"
	sfoConfig.Slots = []Slot{{"controller-a", "10.252.0.10"}, {"controller-b", "10.252.0.11"}, {"controller-c", "10.252.0.12"}}
	gru := linkedRegion{material: filepath.Join(root, "gru"), directory: filepath.Join(root, "gru-interregion")}
	sfo := linkedRegion{material: filepath.Join(root, "sfo"), directory: filepath.Join(root, "sfo-interregion")}
	for _, region := range []struct {
		directory string
		cfg       Config
	}{{gru.material, testConfig()}, {sfo.material, sfoConfig}} {
		if _, err := Generate(region.directory, region.cfg, now); err != nil {
			t.Fatal(err)
		}
	}
	nextSecond()
	topology := natscell.HubAndSpoke("gru", []string{"sfo"})
	var err error
	if gru.record, err = GenerateInterRegion(gru.material, gru.directory, InterRegionConfig{Topology: topology, ListenPort: 7422},
		InterRegionInputs{}, now); err != nil {
		t.Fatal(err)
	}
	if sfo.record, err = GenerateInterRegion(sfo.material, sfo.directory, InterRegionConfig{Topology: topology},
		hubCA(t, gru), now); err != nil {
		t.Fatal(err)
	}
	return gru, sfo, now
}

