func linkVaultProtocol(t *testing.T, store *fakeVault) (*ocivault.VaultsClient, *ocisecrets.SecretsClient) {
	t.Helper()
	endpoint := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		var response any
		var err error
		switch {
		case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, "/secrets"):
			var details ocivault.CreateSecretDetails
			if decodeErr := json.UnmarshalRead(r.Body, &details); decodeErr != nil {
				t.Error(decodeErr)
				w.WriteHeader(http.StatusBadRequest)
				return
			}
			var created ocivault.CreateSecretResponse
			created, err = store.CreateSecret(r.Context(), ocivault.CreateSecretRequest{CreateSecretDetails: details, OpcRetryToken: new(r.Header.Get("opc-retry-token"))})
			response = created.Secret
		case r.Method == http.MethodGet && strings.HasSuffix(r.URL.Path, "/secrets"):
			q := r.URL.Query()
			var listed ocivault.ListSecretsResponse
			listed, err = store.ListSecrets(r.Context(), ocivault.ListSecretsRequest{CompartmentId: new(q.Get("compartmentId")), VaultId: new(q.Get("vaultId")), Name: new(q.Get("name"))})
			response = listed.Items
			if response == nil || listed.Items == nil {
				response = []ocivault.SecretSummary{}
			}
		case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/secretbundles/"):
			_, id, _ := strings.Cut(r.URL.Path, "/secretbundles/")
			var bundle ocisecrets.GetSecretBundleResponse
			bundle, err = store.GetSecretBundle(r.Context(), ocisecrets.GetSecretBundleRequest{SecretId: new(id), VersionNumber: new(int64(1))})
			response = bundle.SecretBundle
		case r.Method == http.MethodGet && strings.Contains(r.URL.Path, "/secrets/"):
			_, id, _ := strings.Cut(r.URL.Path, "/secrets/")
			var secret ocivault.GetSecretResponse
			secret, err = store.GetSecret(r.Context(), ocivault.GetSecretRequest{SecretId: new(id)})
			response = secret.Secret
		default:
			t.Errorf("unexpected OCI request %s %s", r.Method, r.URL.Path)
			w.WriteHeader(http.StatusNotFound)
			return
		}
		if err != nil {
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = w.Write([]byte(`{"code":"InternalError","message":"committed response unavailable"}`))
			return
		}
		if r.Method == http.MethodPost {
			w.WriteHeader(http.StatusOK)
		}
		if err := json.MarshalWrite(w, response); err != nil {
			t.Error(err)
		}
	}))
	t.Cleanup(endpoint.Close)
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	private := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..test", "ocid1.user.oc1..test", store.region, "00:00", string(private), nil)
	management, err := ocivault.NewVaultsClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	bundles, err := ocisecrets.NewSecretsClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	for _, client := range []*common.BaseClient{&management.BaseClient, &bundles.BaseClient} {
		client.Host = endpoint.URL
		client.HTTPClient = endpoint.Client()
		retry := common.NoRetryPolicy()
		client.Configuration.RetryPolicy = &retry
	}
	return &management, &bundles
}

func GenerateSpokeLink(homeMaterialDirectory, homeLinkDirectory string, recipient Record, sourceMetadataSHA, directory string, now time.Time) (LinkRecord, error) {
	wire, err := json.Marshal(recipient)
	if err != nil || digest(wire) != sourceMetadataSHA || recipient.SchemaVersion != 1 || recipient.Config.validate() != nil || recipient.Config.Cell == natscell.LinkHome || now.IsZero() || now.Before(recipient.IssuedAt) || !now.Before(recipient.ExpiresAt) || recipient.ExpiresAt.Sub(recipient.IssuedAt) != time.Duration(recipient.Config.ValidityHours)*time.Hour {
		return LinkRecord{}, ErrMaterial
	}
	if !nkeys.IsValidPublicOperatorKey(recipient.Public.OperatorNKey) {
		return LinkRecord{}, ErrMaterial
	}
	keys := []string{recipient.Public.SystemAccountNKey, recipient.Public.CellAccountNKey, recipient.Public.HostNATSIssuerNKey}
	for index, key := range keys {
		if !nkeys.IsValidPublicAccountKey(key) || slices.Contains(keys[:index], key) {
			return LinkRecord{}, ErrMaterial
		}
	}
	for _, key := range []string{recipient.Public.PeerSignerPublicKey, recipient.Public.LedgerSignerPublicKey, recipient.Public.TicketSignerPublicKey, recipient.Public.ControllerResponsePublicKey} {
		decoded, err := base64.StdEncoding.DecodeString(key)
		if err != nil || len(decoded) != ed25519.PublicKeySize {
			return LinkRecord{}, ErrMaterial
		}
	}
	home, err := Load(homeMaterialDirectory)
	if err != nil || home.Config.Cell != natscell.LinkHome || recipient.Config.Environment != home.Config.Environment || recipient.Config.DeploymentID != home.Config.DeploymentID || recipient.Public.CellAccountNKey == home.Public.CellAccountNKey || recipient.Public.OperatorNKey == home.Public.OperatorNKey {
		return LinkRecord{}, ErrMaterial
	}
	if !filepath.IsAbs(directory) || secureParents(directory) != nil || nested(homeMaterialDirectory, directory) || nested(directory, homeMaterialDirectory) || nested(homeLinkDirectory, directory) || nested(directory, homeLinkDirectory) {
		return LinkRecord{}, ErrMaterial
	}
	homeLink, err := GenerateLink(homeMaterialDirectory, homeMaterialDirectory, homeLinkDirectory, homeLinkDirectory, now)
	if err != nil {
		return LinkRecord{}, err
	}
	homeDigest, err := metadataDigest(homeMaterialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	linkDigest, err := metadataDigest(homeLinkDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	if _, err := os.Lstat(directory); err == nil {
		record, err := LoadLink(directory, now)
		if err != nil || record.SourceSHA256 != sourceMetadataSHA || record.HomeSHA256 != homeDigest || record.HomeLinkSHA256 != linkDigest || record.HomeAccount != homeLink.HomeAccount || record.Signer != homeLink.Signer || !reflect.DeepEqual(record.Config, recipient.Config) || !reflect.DeepEqual(record.Public, recipient.Public) {
			return LinkRecord{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return LinkRecord{}, ErrMaterial
	}
	seed, err := readOwnedFile(filepath.Join(homeLinkDirectory, "issuer-link.seed"), 4096)
	if err != nil {
		return LinkRecord{}, err
	}
	signer, err := nkeys.FromSeed(seed)
	clear(seed)
	if err != nil {
		return LinkRecord{}, err
	}
	defer signer.Wipe()
	record := LinkRecord{SchemaVersion: 1, Config: recipient.Config, Public: recipient.Public, IssuedAt: now.UTC(), ExpiresAt: minTime(recipient.ExpiresAt, homeLink.ExpiresAt), SourceSHA256: sourceMetadataSHA, HomeSHA256: homeDigest, HomeLinkSHA256: linkDigest, HomeAccount: homeLink.HomeAccount, Signer: homeLink.Signer}
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	files[bootstrap.LinkCredentialsFile], err = natscell.IssueLinkUser(signer, record.HomeAccount, recipient.Config.Cell, now, record.ExpiresAt)
	if err != nil {
		return LinkRecord{}, err
	}
	files["interregion-ca.pem"], err = readOwnedFile(filepath.Join(homeMaterialDirectory, "ca.pem"), 64<<10)
	if err != nil {
		return LinkRecord{}, err
	}
	ca, caKey, err := linkCA(files["interregion-ca.pem"], filepath.Join(homeMaterialDirectory, "issuer-ca.key"))
	if err != nil {
		return LinkRecord{}, err
	}
	for _, slot := range recipient.Config.Slots {
		certificate := &x509.Certificate{Subject: pkix.Name{CommonName: recipient.Config.Cell + " " + slot.Name + " link"}, NotBefore: now.Add(-time.Minute), NotAfter: record.ExpiresAt, KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, DNSNames: []string{InterRegionLeafName(recipient.Config.Cell)}}
		cert, key := bootstrap.InterRegionTLSFiles(slot.Name)
		files[cert], files[key], _, _, err = interRegionCertificate(certificate, ca, caKey)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	staging, err := os.MkdirTemp(filepath.Dir(directory), ".spoke-link-")
	if err != nil {
		return LinkRecord{}, err
	}
	defer os.RemoveAll(staging)
	for _, name := range slices.Sorted(maps.Keys(files)) {
		body := files[name]
		if len(body) == 0 || len(body) > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		purpose, slot := linkPurpose(name)
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot, SHA256: digest(body), MaxBytes: int64(len(body))})
		if err := writeOnce(filepath.Join(staging, name), body); err != nil {
			return LinkRecord{}, err
		}
	}
	wire, err = json.Marshal(record)
	if err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, metadataName), wire); err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, readyName), []byte(digest(wire)+"\n")); err != nil {
		return LinkRecord{}, err
	}
	if err := syncDirectory(staging); err != nil {
		return LinkRecord{}, err
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, directory, unix.RENAME_NOREPLACE); err != nil && !errors.Is(err, unix.EEXIST) {
		return LinkRecord{}, err
	}
	if err := syncDirectory(filepath.Dir(directory)); err != nil {
		return LinkRecord{}, err
	}
	return GenerateSpokeLink(homeMaterialDirectory, homeLinkDirectory, recipient, sourceMetadataSHA, directory, now)
}

func GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory string, now time.Time) (LinkRecord, error) {
	material, err := Load(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	home, err := Load(homeMaterialDirectory)
	if err != nil || home.Config.Cell != natscell.LinkHome || material.Config.Environment != home.Config.Environment || material.Config.DeploymentID != home.Config.DeploymentID || now.IsZero() || now.Before(material.IssuedAt) || now.Before(home.IssuedAt) || !now.Before(material.ExpiresAt) || !now.Before(home.ExpiresAt) {
		return LinkRecord{}, ErrMaterial
	}
	isHome := material.Config.Cell == natscell.LinkHome
	if isHome && filepath.Clean(materialDirectory) != filepath.Clean(homeMaterialDirectory) || isHome && filepath.Clean(homeLinkDirectory) != filepath.Clean(directory) || !isHome && (nested(homeLinkDirectory, directory) || nested(directory, homeLinkDirectory)) {
		return LinkRecord{}, ErrMaterial
	}
	for _, source := range []string{materialDirectory, homeMaterialDirectory} {
		if !filepath.IsAbs(directory) || secureParents(directory) != nil || nested(source, directory) || nested(directory, source) {
			return LinkRecord{}, ErrMaterial
		}
	}
	if err := ValidateLive(materialDirectory, material); err != nil {
		return LinkRecord{}, err
	}
	if err := ValidateLive(homeMaterialDirectory, home); err != nil {
		return LinkRecord{}, err
	}
	sourceDigest, err := metadataDigest(materialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	homeDigest, err := metadataDigest(homeMaterialDirectory)
	if err != nil {
		return LinkRecord{}, err
	}
	var homeLink LinkRecord
	homeLinkDigest := ""
	if !isHome {
		homeLink, err = GenerateLink(homeMaterialDirectory, homeMaterialDirectory, homeLinkDirectory, homeLinkDirectory, now)
		if err != nil {
			return LinkRecord{}, err
		}
		homeLinkDigest, err = metadataDigest(homeLinkDirectory)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	if _, err := os.Lstat(directory); err == nil {
		record, err := LoadLink(directory, now)
		if err != nil || record.SourceSHA256 != sourceDigest || record.HomeSHA256 != homeDigest || record.HomeLinkSHA256 != homeLinkDigest || !reflect.DeepEqual(record.Config, material.Config) || !reflect.DeepEqual(record.Public, material.Public) || record.HomeAccount != home.Public.CellAccountNKey || !isHome && record.Signer != homeLink.Signer {
			return LinkRecord{}, ErrMaterial
		}
		return record, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		return LinkRecord{}, ErrMaterial
	}
	var homeClaim *jwt.AccountClaims
	if isHome {
		raw, err := readOwnedFile(filepath.Join(materialDirectory, "cell.jwt"), 64<<10)
		if err != nil {
			return LinkRecord{}, err
		}
		homeClaim, err = jwt.DecodeAccountClaims(string(raw))
		if err != nil || homeClaim.Subject != home.Public.CellAccountNKey || len(homeClaim.Imports) != 0 || len(homeClaim.Exports) != 0 || len(homeClaim.Mappings) != 0 || material.Config.LinkSigner != "" {
			return LinkRecord{}, ErrMaterial
		}
		if homeClaim.IssuedAt >= time.Now().Unix() {
			return LinkRecord{}, fmt.Errorf("%w: home cell claim was issued this second; retry after its issuance second", ErrMaterial)
		}
	}
	// Publish complete source bytes atomically; a crash before publication grants no authority.
	staging, err := os.MkdirTemp(filepath.Dir(directory), ".link-material-")
	if err != nil {
		return LinkRecord{}, err
	}
	defer os.RemoveAll(staging)
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	record := LinkRecord{SchemaVersion: 1, Config: material.Config, Public: material.Public, IssuedAt: now.UTC(), ExpiresAt: minTime(material.ExpiresAt, home.ExpiresAt), SourceSHA256: sourceDigest, HomeSHA256: homeDigest, HomeLinkSHA256: homeLinkDigest, HomeAccount: home.Public.CellAccountNKey}
	var signer nkeys.KeyPair
	if isHome {
		signer, err = nkeys.CreateAccount()
		if err != nil {
			return LinkRecord{}, err
		}
		files["issuer-link.seed"], err = signer.Seed()
	} else {
		record.ExpiresAt = minTime(record.ExpiresAt, homeLink.ExpiresAt)
		seed, readErr := readOwnedFile(filepath.Join(homeLinkDirectory, "issuer-link.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		signer, err = nkeys.FromSeed(seed)
		clear(seed)
	}
	if err != nil {
		return LinkRecord{}, err
	}
	defer signer.Wipe()
	record.Signer, err = signer.PublicKey()
	if err != nil {
		return LinkRecord{}, err
	}
	if isHome {
		claim := homeClaim
		previousIssue := claim.IssuedAt
		natscell.ApplyLink(claim, record.Signer)
		seed, readErr := readOwnedFile(filepath.Join(materialDirectory, "issuer-operator.seed"), 4096)
		if readErr != nil {
			return LinkRecord{}, readErr
		}
		operator, decodeErr := nkeys.FromSeed(seed)
		clear(seed)
		if decodeErr != nil {
			return LinkRecord{}, decodeErr
		}
		claim.IssuedAt, claim.Expires = now.Unix(), record.ExpiresAt.Unix()
		encoded, encodeErr := claim.Encode(operator)
		operator.Wipe()
		if encodeErr != nil {
			return LinkRecord{}, encodeErr
		}
		if claim.IssuedAt <= previousIssue {
			return LinkRecord{}, ErrMaterial
		}
		files["link-cell.jwt"] = []byte(encoded)
	} else {
		files[bootstrap.LinkCredentialsFile], err = natscell.IssueLinkUser(signer, record.HomeAccount, material.Config.Cell, now, record.ExpiresAt)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	files["interregion-ca.pem"], err = readOwnedFile(filepath.Join(homeMaterialDirectory, "ca.pem"), 64<<10)
	if err != nil {
		return LinkRecord{}, err
	}
	ca, key, err := linkCA(files["interregion-ca.pem"], filepath.Join(homeMaterialDirectory, "issuer-ca.key"))
	if err != nil {
		return LinkRecord{}, err
	}
	for _, slot := range material.Config.Slots {
		template := &x509.Certificate{Subject: pkix.Name{CommonName: material.Config.Cell + " " + slot.Name + " link"}, NotBefore: now.Add(-time.Minute), NotAfter: record.ExpiresAt, KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}, DNSNames: []string{InterRegionLeafName(material.Config.Cell)}}
		if isHome {
			template.ExtKeyUsage = append(template.ExtKeyUsage, x509.ExtKeyUsageServerAuth)
			template.DNSNames = []string{natscell.LinkServerName}
		}
		certName, keyName := bootstrap.InterRegionTLSFiles(slot.Name)
		files[certName], files[keyName], _, _, err = interRegionCertificate(template, ca, key)
		if err != nil {
			return LinkRecord{}, err
		}
	}
	for _, name := range slices.Sorted(maps.Keys(files)) {
		purpose, slot := linkPurpose(name)
		body := files[name]
		if len(body) == 0 || len(body) > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		record.Files = append(record.Files, File{Name: name, Purpose: purpose, Slot: slot, SHA256: digest(body), MaxBytes: int64(len(body))})
		if err := writeOnce(filepath.Join(staging, name), body); err != nil {
			return LinkRecord{}, err
		}
	}
	wire, err := json.Marshal(record)
	if err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, metadataName), wire); err != nil {
		return LinkRecord{}, err
	}
	if err := writeOnce(filepath.Join(staging, readyName), []byte(digest(wire)+"\n")); err != nil {
		return LinkRecord{}, err
	}
	if err := syncDirectory(staging); err != nil {
		return LinkRecord{}, err
	}
	if err := unix.Renameat2(unix.AT_FDCWD, staging, unix.AT_FDCWD, directory, unix.RENAME_NOREPLACE); err != nil && !errors.Is(err, unix.EEXIST) {
		return LinkRecord{}, err
	}
	if err := syncDirectory(filepath.Dir(directory)); err != nil {
		return LinkRecord{}, err
	}
	return GenerateLink(materialDirectory, homeMaterialDirectory, homeLinkDirectory, directory, now)
}

func LoadLink(directory string, now time.Time) (LinkRecord, error) {
	if !filepath.IsAbs(directory) || secureParents(directory) != nil || secureDirectory(directory) != nil {
		return LinkRecord{}, ErrMaterial
	}
	wire, err := readOwnedFile(filepath.Join(directory, metadataName), 1<<20)
	if err != nil {
		return LinkRecord{}, err
	}
	ready, err := readOwnedFile(filepath.Join(directory, readyName), 128)
	if err != nil || string(ready) != digest(wire)+"\n" {
		return LinkRecord{}, ErrMaterial
	}
	var record LinkRecord
	if json.Unmarshal(wire, &record, json.RejectUnknownMembers(true)) != nil || record.SchemaVersion != 1 || record.Config.validate() != nil || len(record.SourceSHA256) != 64 || len(record.HomeSHA256) != 64 || !nkeys.IsValidPublicAccountKey(record.HomeAccount) || !nkeys.IsValidPublicAccountKey(record.Signer) || record.Signer == record.HomeAccount || now.Before(record.IssuedAt) || !now.Before(record.ExpiresAt) {
		return LinkRecord{}, ErrMaterial
	}
	home := record.Config.Cell == natscell.LinkHome
	expected := map[string]bool{"interregion-ca.pem": true}
	if home {
		expected["link-cell.jwt"], expected["issuer-link.seed"] = true, true
	} else {
		expected[bootstrap.LinkCredentialsFile] = true
		if len(record.HomeLinkSHA256) != 64 {
			return LinkRecord{}, ErrMaterial
		}
	}
	for _, slot := range record.Config.Slots {
		cert, key := bootstrap.InterRegionTLSFiles(slot.Name)
		expected[cert], expected[key] = true, true
	}
	if len(record.Files) != len(expected) {
		return LinkRecord{}, ErrMaterial
	}
	files := map[string][]byte{}
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	allowed := map[string]bool{metadataName: true, readyName: true, journalName: true, journalTempName: true, journalLockName: true}
	for _, file := range record.Files {
		purpose, slot := linkPurpose(file.Name)
		if !expected[file.Name] || files[file.Name] != nil || purpose != file.Purpose || slot != file.Slot || file.MaxBytes <= 0 || file.MaxBytes > maxInterRegionFile {
			return LinkRecord{}, ErrMaterial
		}
		body, err := readOwnedFile(filepath.Join(directory, file.Name), file.MaxBytes)
		if err != nil || int64(len(body)) != file.MaxBytes || digest(body) != file.SHA256 {
			clear(body)
			return LinkRecord{}, ErrMaterial
		}
		files[file.Name] = body
		allowed[file.Name] = true
	}
	entries, err := os.ReadDir(directory)
	if err != nil {
		return LinkRecord{}, err
	}
	for _, entry := range entries {
		if !allowed[entry.Name()] {
			return LinkRecord{}, ErrMaterial
		}
	}
	if home {
		claim, err := jwt.DecodeAccountClaims(string(files["link-cell.jwt"]))
		if err != nil || claim.Subject != record.HomeAccount || claim.Issuer != record.Public.OperatorNKey || natscell.VerifyLinkScope(claim) != nil {
			return LinkRecord{}, ErrMaterial
		}
		if scope, ok := claim.SigningKeys.GetScope(record.Signer); !ok || !reflect.DeepEqual(scope, natscell.LinkScope(record.Signer)) {
			return LinkRecord{}, ErrMaterial
		}
		signer, err := nkeys.FromSeed(files["issuer-link.seed"])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		public, err := signer.PublicKey()
		signer.Wipe()
		if err != nil || public != record.Signer {
			return LinkRecord{}, ErrMaterial
		}
	} else {
		if natscell.ValidateLinkCredentialBytes(files[bootstrap.LinkCredentialsFile], record.Config.Cell) != nil {
			return LinkRecord{}, ErrMaterial
		}
		raw, err := jwt.ParseDecoratedJWT(files[bootstrap.LinkCredentialsFile])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		claim, err := jwt.DecodeUserClaims(raw)
		if err != nil || claim.Issuer != record.Signer || claim.IssuerAccount != record.HomeAccount {
			return LinkRecord{}, ErrMaterial
		}
	}
	roots := x509.NewCertPool()
	if !roots.AppendCertsFromPEM(files["interregion-ca.pem"]) {
		return LinkRecord{}, ErrMaterial
	}
	for _, slot := range record.Config.Slots {
		cert, key := bootstrap.InterRegionTLSFiles(slot.Name)
		pair, err := tls.X509KeyPair(files[cert], files[key])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		leaf, err := x509.ParseCertificate(pair.Certificate[0])
		if err != nil {
			return LinkRecord{}, ErrMaterial
		}
		usages := []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}
		if home {
			usages = append(usages, x509.ExtKeyUsageServerAuth)
		}
		if _, err := leaf.Verify(x509.VerifyOptions{Roots: roots, CurrentTime: now, DNSName: InterRegionLeafName(record.Config.Cell), KeyUsages: usages}); err != nil || leaf.IsCA || leaf.NotAfter.After(record.ExpiresAt) {
			return LinkRecord{}, ErrMaterial
		}
	}
	return record, nil
}

func RenderLink(record LinkRecord, slot, directory string) (natscell.Link, error) {
	if !filepath.IsAbs(directory) || !slices.ContainsFunc(record.Config.Slots, func(s Slot) bool { return s.Name == slot }) {
		return natscell.Link{}, ErrMaterial
	}
	cert, key := bootstrap.InterRegionTLSFiles(slot)
	link := natscell.Link{TLS: natscell.TLSFiles{CAFile: filepath.Join(directory, "interregion-ca.pem"), CertFile: filepath.Join(directory, cert), KeyFile: filepath.Join(directory, key)}}
	if record.Config.Cell != natscell.LinkHome {
		link.CredentialsFile = filepath.Join(directory, bootstrap.LinkCredentialsFile)
	}
	return link, nil
}

// ProvisionLink publishes host files using regional recovery and OCI retry tokens.
// The home signing seed stays in the founder-only source escrow.
func ProvisionLink(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time) (Publication, error) {
	return provisionLink(ctx, directory, target, management, bundles, now, nil)
}

// ProvisionLinkDurable preserves the publication journal through source authority
// checkpoints before issuing any Vault secret create.
func ProvisionLinkDurable(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time, checkpoint func([]byte) error) (Publication, error) {
	if checkpoint == nil {
		return Publication{}, ErrProvision
	}
	return provisionLink(ctx, directory, target, management, bundles, now, checkpoint)
}

func provisionLink(ctx context.Context, directory string, target VaultTarget, management VaultClient, bundles BundleClient, now time.Time, checkpoint func([]byte) error) (Publication, error) {
	record, err := LoadLink(directory, now)
	if err != nil || management == nil || bundles == nil || ctx.Err() != nil || target.validate(record.Config.Region) != nil {
		return Publication{}, ErrProvision
	}
	ctx, cancel := context.WithDeadline(ctx, record.ExpiresAt)
	defer cancel()
	fd, err := syscall.Open(filepath.Join(directory, journalLockName), syscall.O_RDWR|syscall.O_CREAT|syscall.O_NOFOLLOW|syscall.O_CLOEXEC, 0o600)
	if err != nil {
		return Publication{}, ErrProvision
	}
	lock := os.NewFile(uintptr(fd), journalLockName)
	defer lock.Close()
	if ownedRegular(filepath.Join(directory, journalLockName), 0, 0) != nil {
		return Publication{}, ErrProvision
	}
	if err := syscall.Flock(fd, syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		return Publication{}, ErrProvision
	}
	defer syscall.Flock(fd, syscall.LOCK_UN)
	materialDigest, err := metadataDigest(directory)
	if err != nil {
		return Publication{}, ErrProvision
	}
	state, err := loadJournal(ctx, directory, record.Record, target, materialDigest, checkpoint)
	if err != nil {
		return Publication{}, err
	}
	result := Publication{SchemaVersion: 1, Target: target, MaterialSHA256: materialDigest}
	for index := range state.Entries {
		entry := &state.Entries[index]
		file, ok := findFile(record.Record, entry.FileName)
		if !ok || ctx.Err() != nil {
			return Publication{}, ErrProvision
		}
		if err := publishOne(ctx, directory, target, record.Config.Region, management, bundles, file, entry, &state, now, checkpoint); err != nil {
			return Publication{}, err
		}
		result.References = append(result.References, PublicReference{SecretName: entry.Name, Reference: bootstrap.SecretReference{Purpose: file.Purpose, Slot: file.Slot, SecretOCID: entry.SecretOCID, VersionNumber: 1, SHA256: file.SHA256, MaxBytes: file.MaxBytes, TargetFile: file.Name}})
	}
	return result, nil
}

func ValidateLinkPublication(directory string, publication Publication, journalWire []byte, now time.Time) error {
	record, err := LoadLink(directory, now)
	if err != nil {
		return ErrProvision
	}
	return validatePublication(directory, record.Record, publication, journalWire)
}

func IssueLinkUser(signer nkeys.KeyPair, homeAccount, cell string, issuedAt, expires time.Time) ([]byte, error) {
	if token, err := protocol.RegionToken(cell); err != nil || token != cell || cell == protocol.GlobalScope || cell == LinkHome {
		return nil, errors.New("link user cell must be a lowercase spoke region")
	}
	if !nkeys.IsValidPublicAccountKey(homeAccount) {
		return nil, errors.New("link user home account must be an account public key")
	}
	if signer == nil {
		return nil, errors.New("link user requires a scoped account signing key")
	}
	signingKey, err := signer.PublicKey()
	if err != nil || !nkeys.IsValidPublicAccountKey(signingKey) || signingKey == homeAccount {
		return nil, errors.New("link user requires a scoped account signing key distinct from the home account")
	}
	if issuedAt.IsZero() || issuedAt.Unix() > time.Now().Unix() || expires.Unix() <= issuedAt.Unix() || expires.Unix() <= time.Now().Unix() {
		return nil, errors.New("link user validity must be current with an expiration after its issuance")
	}
	user, err := nkeys.CreateUser()
	if err != nil {
		return nil, err
	}
	defer user.Wipe()
	public, err := user.PublicKey()
	if err != nil {
		return nil, err
	}
	seed, err := user.Seed()
	if err != nil {
		return nil, err
	}
	claim := jwt.NewUserClaims(public)
	claim.UserPermissionLimits = jwt.UserPermissionLimits{}
	claim.IssuerAccount = homeAccount
	claim.Tags = jwt.TagList{"cell:" + cell}
	claim.IssuedAt, claim.Expires = issuedAt.Unix(), expires.Unix()
	raw, err := claim.Encode(signer)
	if err != nil {
		return nil, err
	}
	return jwt.FormatUserConfig(raw, seed)
}

func linkServerOptions(cfg Config, options *server.Options, resolver *accountResolver) error {
	link := cfg.Embedded.Link
	cellClaim, err := jwt.DecodeAccountClaims(resolver.claims[resolver.cell])
	if err != nil {
		return err
	}
	if err := verifyLinkAccount(cellClaim, cfg.Cell); err != nil {
		return err
	}
	// The link rides the cell account, so the leaf accounts are the cell's.
	resolver.interregion = resolver.cell
	resolver.linkCell = cfg.Cell
	options.LeafNode.NoAdvertise = true
	// Same fast stale-path detection as the interregion leaves.
	options.PingInterval, options.MaxPingsOut = 10*time.Second, 3
	if cfg.Cell == LinkHome {
		listenTLS, err := loadTLS(link.TLS, true)
		if err != nil {
			return fmt.Errorf("link listener TLS: %w", err)
		}
		options.LeafNode.Host = "0.0.0.0"
		options.LeafNode.Port = linkListenPort
		options.LeafNode.TLSConfig = listenTLS
		options.LeafNode.TLSTimeout = 5
		return nil
	}
	if err := validateLinkCredentials(link.CredentialsFile, cfg.Cell); err != nil {
		return fmt.Errorf("link credentials: %w", err)
	}
	remoteTLS, err := loadTLS(link.TLS, false)
	if err != nil {
		return fmt.Errorf("link TLS: %w", err)
	}
	remoteTLS.ServerName = linkServerName
	leaf := &server.RemoteLeafOpts{
		LocalAccount: resolver.cell, Credentials: link.CredentialsFile,
		TLS: true, TLSConfig: remoteTLS, TLSTimeout: 5, NoRandomize: true,
		// The home cannot push regional-only families either.
		DenyImports: []string{"$JS.API.>", "$KV.>", "$O.>", "$SYS.>", protocol.ControlRoot + ".>", protocol.BrokerRoot + ".>"},
	}
	for _, raw := range linkHomeURLs {
		parsed, err := url.Parse(raw)
		if err != nil {
			return err
		}
		leaf.URLs = append(leaf.URLs, parsed)
	}
	options.LeafNode.Remotes = append(options.LeafNode.Remotes, leaf)
	return nil
}

func loadRecordedControllerIssuer(record Record, read func(string) ([]byte, error), now time.Time) (*ControllerIssuer, error) {
	if record.SchemaVersion != 1 || record.Config.validate() != nil || now.Before(record.IssuedAt) || !now.Before(record.ExpiresAt) ||
		record.ExpiresAt.Sub(record.IssuedAt) != time.Duration(record.Config.ValidityHours)*time.Hour ||
		!nkeys.IsValidPublicOperatorKey(record.Public.OperatorNKey) || !nkeys.IsValidPublicAccountKey(record.Public.CellAccountNKey) ||
		!nkeys.IsValidPublicAccountKey(record.Public.ControllerAccountSignerNKey) ||
		record.Public.ControllerAccountSignerNKey == record.Public.CellAccountNKey || record.Public.ControllerAccountSignerNKey == record.Public.HostNATSIssuerNKey {
		return nil, ErrMaterial
	}
	inventory := make(map[string]File, len(record.Files))
	for _, file := range record.Files {
		purpose, slot := classify(file.Name)
		if _, exists := inventory[file.Name]; exists || purpose == "" || file.Purpose != purpose || file.Slot != slot || file.MaxBytes <= 0 || file.MaxBytes > bootstrap.MaxSecretBytes {
			return nil, ErrMaterial
		}
		inventory[file.Name] = file
	}
	files := make(map[string][]byte)
	defer func() {
		for _, body := range files {
			clear(body)
		}
	}()
	for _, name := range []string{"ca.pem", "operator.jwt", "cell.jwt", "controller-tls-issuer-cert.pem", "controller-tls-issuer-key.pem", "controller-account-signer.seed"} {
		file, exists := inventory[name]
		if !exists {
			return nil, ErrMaterial
		}
		body, err := read(name)
		if err != nil {
			return nil, err
		}
		files[name] = bytes.Clone(body)
		if int64(len(body)) != file.MaxBytes || digest(body) != file.SHA256 {
			return nil, ErrMaterial
		}
	}
	check := generationCheck{now: now}
	roots := check.bundle("ca.pem", files["ca.pem"])
	cert, err := controllerIssuer(files["controller-tls-issuer-key.pem"], files["controller-tls-issuer-cert.pem"], roots)
	if err != nil {
		return nil, err
	}
	check.certificate("controller-tls-issuer-cert.pem", cert)
	if cert.NotAfter.After(minTime(record.ExpiresAt, record.IssuedAt.Add(controllerIssuedLifetime))) ||
		cert.KeyUsage != x509.KeyUsageCertSign || !cert.BasicConstraintsValid ||
		len(cert.PermittedDNSDomains)+len(cert.PermittedURIDomains)+len(cert.PermittedIPRanges)+len(cert.PermittedEmailAddresses)+
			len(cert.ExcludedDNSDomains)+len(cert.ExcludedURIDomains)+len(cert.ExcludedIPRanges)+len(cert.ExcludedEmailAddresses) != 0 {
		return nil, ErrMaterial
	}
	operator, err := jwt.DecodeOperatorClaims(strings.TrimSpace(string(files["operator.jwt"])))
	if err != nil || operator.Subject != record.Public.OperatorNKey || operator.Issuer != operator.Subject ||
		!operator.DidSign(operator) || operator.SystemAccount != record.Public.SystemAccountNKey || len(operator.SigningKeys) != 0 || operator.Expires == 0 {
		return nil, ErrMaterial
	}
	validation := jwt.CreateValidationResults()
	operator.Validate(validation)
	check.jwt("operator.jwt", operator.IssuedAt, operator.Expires)
	account, err := jwt.DecodeAccountClaims(strings.TrimSpace(string(files["cell.jwt"])))
	if err != nil || account.Subject != record.Public.CellAccountNKey || account.Issuer != record.Public.OperatorNKey || !operator.DidSign(account) || account.Expires == 0 {
		return nil, ErrMaterial
	}
	account.Validate(validation)
	check.jwt("cell.jwt", account.IssuedAt, account.Expires)
	scope, exists := account.SigningKeys.GetScope(record.Public.ControllerAccountSignerNKey)
	if !exists || scope != nil || validation.IsBlocking(true) || len(check.problems) != 0 {
		return nil, ErrMaterial
	}
	for key, scope := range account.SigningKeys {
		if scope == nil && key != record.Public.ControllerAccountSignerNKey {
			return nil, ErrMaterial
		}
	}
	return loadControllerIssuer(issuerIdentity{Cell: strings.ToUpper(record.Config.Cell), Environment: record.Config.Environment,
		Operator: record.Public.OperatorNKey, CellAccount: record.Public.CellAccountNKey, AccountSigner: record.Public.ControllerAccountSignerNKey,
		lifetime: controllerIssuedLifetime, expiresAt: minTime(record.ExpiresAt, minTime(time.Unix(operator.Expires, 0), time.Unix(account.Expires, 0)))},
		files["controller-tls-issuer-cert.pem"], files["controller-tls-issuer-key.pem"], files["controller-account-signer.seed"])
}

func loadControllerIssuer(identity issuerIdentity, certPEM, keyPEM, signerSeed []byte) (*ControllerIssuer, error) {
	block, _ := pem.Decode(certPEM)
	if block == nil {
		return nil, errors.New("controller TLS issuer certificate is invalid")
	}
	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("controller TLS issuer certificate: %w", err)
	}
	if identity.expiresAt.IsZero() || cert.NotAfter.Before(identity.expiresAt) {
		identity.expiresAt = cert.NotAfter
	}
	keyBlock, _ := pem.Decode(keyPEM)
	if keyBlock == nil {
		return nil, errors.New("controller TLS issuer key is invalid")
	}
	key, err := x509.ParseECPrivateKey(keyBlock.Bytes)
	if err != nil {
		return nil, fmt.Errorf("controller TLS issuer key: %w", err)
	}
	signer, err := nkeys.FromSeed([]byte(strings.TrimSpace(string(signerSeed))))
	if err != nil {
		return nil, errors.New("controller account signer seed is invalid")
	}
	if public, err := signer.PublicKey(); err != nil || public != identity.AccountSigner {
		signer.Wipe()
		return nil, errors.New("controller account signer differs from the generation's")
	}
	return &ControllerIssuer{identity: identity, certPEM: pem.EncodeToMemory(block), cert: cert, key: key,
		signer: signer}, nil
}

// Wipe clears the account signer seed.
func (issuer *ControllerIssuer) Wipe() { issuer.signer.Wipe() }

func (issuer *ControllerIssuer) lifetime() time.Duration {
	return issuer.identity.lifetime
}

// RenewTLS issues a leaf with identity and a fresh key, valid for the
// generation's issued lifetime and never past the issuer. certPEM holds the
// leaf followed by the issuer, so peers can build the chain to the bundle.
func (issuer *ControllerIssuer) RenewTLS(identity LeafIdentity, now time.Time) (certPEM, keyPEM []byte, err error) {
	if issuer == nil || issuer.cert == nil || issuer.key == nil || !now.Before(issuer.identity.expiresAt) {
		return nil, nil, errors.New("controller TLS issuer has expired")
	}
	ip := net.ParseIP(identity.IP)
	if identity.CommonName == "" || identity.DNSName == "" || ip == nil {
		return nil, nil, errors.New("controller leaf identity is incomplete")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return nil, nil, err
	}
	notAfter := now.Add(issuer.lifetime() - issuedBackdate)
	if notAfter.After(issuer.identity.expiresAt) {
		notAfter = issuer.identity.expiresAt
	}
	template := &x509.Certificate{SerialNumber: serial, Subject: pkix.Name{CommonName: identity.CommonName},
		NotBefore: now.Add(-issuedBackdate), NotAfter: notAfter, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth},
		IPAddresses: []net.IP{ip}, DNSNames: []string{identity.DNSName}}
	der, err := x509.CreateCertificate(rand.Reader, template, issuer.cert, &key.PublicKey, issuer.key)
	if err != nil {
		return nil, nil, err
	}
	keyDER, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return nil, nil, err
	}
	leaf := pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der})
	return append(leaf, issuer.certPEM...), pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER}), nil
}

func (issuer *ControllerIssuer) IssueFunctionCredentials(admitted release.VerifiedFunction, accountJWT string, existing []byte) ([]byte, functions.WorkerBrokerIdentity, error) {
	if issuer == nil || issuer.cert == nil || issuer.key == nil || !admitted.Valid() || !time.Now().Before(issuer.identity.expiresAt) {
		return nil, functions.WorkerBrokerIdentity{}, errors.New("function issuance requires a current admitted release and controller generation")
	}
	claim := admitted.Claim()
	account, err := jwt.DecodeAccountClaims(accountJWT)
	if err != nil || account.Subject != issuer.identity.CellAccount || account.Issuer != issuer.identity.Operator ||
		claim.Environment != issuer.identity.Environment || claim.Cell != issuer.identity.Cell {
		return nil, functions.WorkerBrokerIdentity{}, errors.New("function release or broker account differs from the controller generation")
	}
	credentials, identity, err := functions.IssueWorkerCredentials(admitted, issuer.identity.CellAccount, accountJWT, issuer.signer, existing)
	if err != nil {
		return nil, functions.WorkerBrokerIdentity{}, err
	}
	if identity.ExpiresAt.After(issuer.identity.expiresAt) {
		clear(credentials)
		return nil, functions.WorkerBrokerIdentity{}, errors.New("function credentials outlive the current controller authority")
	}
	return credentials, identity, nil
}

// IssueFunctionTLS issues only the admitted function's fixed server identity.
// The returned issuer certificate is public; its signing key stays here.
func (issuer *ControllerIssuer) IssueFunctionTLS(admitted release.VerifiedFunction) (certPEM, keyPEM, issuerPEM []byte, err error) {
	return issuer.issueFunctionTLS(admitted, x509.ExtKeyUsageServerAuth)
}

// IssueFunctionClientTLS issues only the admitted tenant/function's client identity.
func (issuer *ControllerIssuer) IssueFunctionClientTLS(admitted release.VerifiedFunction) (certPEM, keyPEM, issuerPEM []byte, err error) {
	return issuer.issueFunctionTLS(admitted, x509.ExtKeyUsageClientAuth)
}

func (issuer *ControllerIssuer) issueFunctionTLS(admitted release.VerifiedFunction, usage x509.ExtKeyUsage) (certPEM, keyPEM, issuerPEM []byte, err error) {
	if issuer == nil || issuer.cert == nil || issuer.key == nil || !admitted.Valid() {
		return nil, nil, nil, errors.New("function TLS issuance requires a current admitted release and controller generation")
	}
	claim := admitted.Claim()
	now := time.Now()
	expires := minTime(minTime(admitted.ExpiresAt(), now.Add(time.Hour)), issuer.identity.expiresAt)
	if claim.Environment != issuer.identity.Environment || claim.Cell != issuer.identity.Cell ||
		now.Before(issuer.cert.NotBefore) || !now.Before(expires) {
		return nil, nil, nil, errors.New("function TLS release differs from the current controller generation")
	}
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return nil, nil, nil, err
	}
	serial, err := rand.Int(rand.Reader, new(big.Int).Lsh(big.NewInt(1), 128))
	if err != nil {
		return nil, nil, nil, err
	}
	name := claim.FunctionID + "." + strings.ToLower(claim.TenantID) + ".functions." + strings.ToLower(claim.Cell) + ".terrascale.internal"
	template := &x509.Certificate{SerialNumber: serial, Subject: pkix.Name{CommonName: name},
		NotBefore: now.Add(-issuedBackdate), NotAfter: expires, KeyUsage: x509.KeyUsageDigitalSignature,
		ExtKeyUsage: []x509.ExtKeyUsage{usage},
		URIs:        []*url.URL{{Scheme: "spiffe", Host: "terrascale.tech", Path: "/tenants/" + claim.TenantID + "/functions/" + claim.FunctionID}}}
	if usage == x509.ExtKeyUsageServerAuth {
		template.DNSNames = []string{name}
	}
	der, err := x509.CreateCertificate(rand.Reader, template, issuer.cert, &key.PublicKey, issuer.key)
	if err != nil {
		return nil, nil, nil, err
	}
	keyDER, err := x509.MarshalECPrivateKey(key)
	if err != nil {
		return nil, nil, nil, err
	}
	defer clear(keyDER)
	return append(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}), issuer.certPEM...),
		pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER}), bytes.Clone(issuer.certPEM), nil
}

func startupFunctionProof(t *testing.T, tenant, function, cell, environment string, now time.Time, validFor time.Duration) release.VerifiedFunction {
	t.Helper()
	module := []byte("\x00asm\x01\x00\x00\x00")
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI, TenantID: tenant, FunctionID: function, Revision: "first",
		Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)), Environment: environment, Cell: cell, Sequence: 1}
	root, rootKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leaf, key, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leaf)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(leaf)
	if err != nil {
		t.Fatal(err)
	}
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded,
		Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: scope.Environment,
			Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}}, now.Add(-time.Minute), now.Add(validFor+time.Hour), rootKey)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := release.SignFunctionClaim(claim, module, delegation, roots, key, now, validFor)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	delegationWire, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, delegationWire, module, roots, release.FunctionExpectation{Environment: environment, Cell: cell,
		TenantID: tenant, FunctionID: function, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: claim.Sequence}, now)
	if err != nil {
		t.Fatal(err)
	}
	return proof
}
